// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.20;

interface IInvestmentHandler {
    struct VaultInfo {
        address lpToken;             // LP token address
        address assetToken;          // Asset token
        uint256 lpAmount;            // Total LP tokens/shares held by this investment
        uint256 totalValueInAsset;   // Value of totalAmount LP tokens converted to underlying asset
    }

    /// @notice Preview how many shares would be received for a deposit
    /// @param amount Amount of assets to deposit
    /// @return shares Expected amount of LP tokens/shares to receive
    function previewDeposit(uint256 amount) external view returns (uint256 shares);

    /// @notice Preview how many assets would be received for a redemption
    /// @param shares Amount of LP tokens/shares to redeem
    /// @return assets Expected amount of assets to receive
    function previewWithdraw(uint256 shares) external view returns (uint256 assets);

    /// @notice Deposit assets and receive LP tokens/shares
    function deposit(
        address receiver,
        address tokenIn,
        uint256 amount,
        uint256 minLpAmount
    ) external payable returns (uint256);

    /// @notice Withdraw assets by burning LP tokens/shares
    function withdraw(
        address receiver,
        address tokenOut,
        uint256 sharesAmount,
        uint256 minTokenOut
    ) external returns (uint256);

    /// @notice Get comprehensive vault information for a specific account
    /// @param account The account to query vault info for
    function vaultInfo(address account) view external returns (VaultInfo[] memory assets);
}

