// SPDX-License-Identifier: BUSL-1.1

pragma solidity ^0.8.20;

import "./../interfaces/IInvestmentHandler.sol";
import "./../interfaces/ICToken.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

contract CInvestmentHandler is IInvestmentHandler {
    ICToken public immutable cToken;
    address public immutable assetToken;

    constructor(address _cToken) {
        cToken = ICToken(_cToken);
        assetToken = cToken.asset();
    }

    /// @notice Preview how many shares would be received for a deposit
    /// @param amount Amount of assets to deposit
    /// @return shares Expected amount of cToken shares to receive
    function previewDeposit(uint256 amount) external view override returns (uint256 shares) {
        return cToken.previewDeposit(amount);
    }

    /// @notice Preview how many assets would be received for a withdrawal
    /// @param shares Amount of cToken shares to redeem
    /// @return assets Expected amount of assets to receive
    function previewWithdraw(uint256 shares) external view override returns (uint256 assets) {
        return cToken.convertToAssets(shares);
    }

    /// @notice Deposit assets into CToken market
    /// @param receiver The account that will receive the shares
    /// @param tokenIn The underlying asset to deposit (must match cToken.asset())
    /// @param minLpAmount Minimum shares to receive (slippage protection)
    /// @return shares The amount of shares minted
    function deposit(
        address receiver,
        address tokenIn,
        uint256 amount,
        uint256 minLpAmount
    ) external payable returns (uint256) {
        require(tokenIn == assetToken, "Invalid token");
        require(amount > 0, "Amount must be greater than 0");

        // Transfer tokens from sender to this contract
        IERC20(tokenIn).transferFrom(msg.sender, address(this), amount);

        // Approve cToken to spend tokens
        IERC20(tokenIn).approve(address(cToken), amount);

        // Deposit into cToken market
        uint256 shares = cToken.deposit(amount, receiver);

        require(shares >= minLpAmount, "Slippage: shares < minLpAmount");

        return shares;
    }

    /// @notice Withdraw assets from CToken market
    /// @param receiver The account that will receive the assets
    /// @param tokenOut The underlying asset to withdraw (must match cToken.asset())
    /// @param sharesAmount Amount of shares to redeem
    /// @param minTokenOut Minimum amount of assets to receive (slippage protection)
    /// @return assets The amount of assets withdrawn
    function withdraw(
        address receiver,
        address tokenOut,
        uint256 sharesAmount,
        uint256 minTokenOut
    ) external returns (uint256) {
        require(tokenOut == assetToken, "Invalid token");
        require(sharesAmount > 0, "Shares amount must be greater than 0");

        // Pull cToken shares from msg.sender (Strategy) to this contract
        // Strategy must approve this contract to spend cToken shares first
        IERC20(address(cToken)).transferFrom(msg.sender, address(this), sharesAmount);

        // Redeem shares owned by this contract, send assets to receiver
        uint256 assets = cToken.redeem(sharesAmount, receiver, address(this));

        require(assets >= minTokenOut, "Slippage: assets < minTokenOut");

        return assets;
    }

    /// @notice Get comprehensive vault information for a specific account
    /// @param account The account to query vault info for
    /// @return assets Array containing complete info about all underlying tokens
    function vaultInfo(address account)
        external
        view
        override
        returns (VaultInfo[] memory assets)
    {
        // Create array with single asset info for CToken (single underlying)
        assets = new VaultInfo[](1);

        address lpTokenAddr = address(cToken);      // CToken is the LP token
        address assetTokenAddr = assetToken;   // Underlying asset (cached)

        // Total LP tokens held by the account
        uint256 totalLpAmount = cToken.balanceOf(account);

        // Convert LP tokens to underlying asset value
        uint256 totalValueInAsset = cToken.convertToAssets(totalLpAmount);

        assets[0] = VaultInfo({
            lpToken: lpTokenAddr,
            assetToken: assetTokenAddr,
            lpAmount: totalLpAmount,
            totalValueInAsset: totalValueInAsset
        });

        return assets;
    }
}

