// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.20;

import "./../interfaces/IInvestmentHandler.sol";
import "./../interfaces/IShMonad.sol";
import "./../interfaces/IWMON.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

contract ShMonadInvestmentHandler is IInvestmentHandler {
    IERC4626Custom public immutable shMonad;
    address public immutable assetToken;
    address public immutable wmon;

    constructor(address _shMonad, address _wmon) {
        shMonad = IERC4626Custom(_shMonad);
        assetToken = shMonad.asset();
        wmon = _wmon;

        require(assetToken == address(0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE), "ShMonad must accept native token");
    }

    /// @notice Preview how many shares would be received for a deposit
    /// @param amount Amount of assets to deposit
    /// @return shares Expected amount of shMON shares to receive
    function previewDeposit(uint256 amount) external view override returns (uint256 shares) {
        return shMonad.previewDeposit(amount);
    }

    /// @notice Preview how many assets would be received for a withdrawal
    /// @param shares Amount of shMON shares to redeem
    /// @return assets Expected amount of assets to receive
    function previewWithdraw(uint256 shares) external view override returns (uint256 assets) {
        return shMonad.previewRedeem(shares);
    }

    /// @notice Deposit assets into ShMonad vault and receive shMON shares
    /// @param receiver The account that will receive the shares
    /// @param tokenIn The token being deposited (WMON)
    /// @param amount Amount of assets to deposit
    /// @param minLpAmount Minimum shares to receive (slippage protection)
    /// @return shares The amount of shMON shares minted
    function deposit(
        address receiver,
        address tokenIn,
        uint256 amount,
        uint256 minLpAmount
    ) external payable override returns (uint256) {
        require(tokenIn == wmon, "Token must be WMON");
        require(amount > 0, "Amount must be greater than 0");

        // Transfer WMON from sender (Strategy) to this contract
        IERC20(wmon).transferFrom(msg.sender, address(this), amount);

        // Unwrap WMON to get native MON
        IWMON(wmon).withdraw(amount);

        // Deposit native MON into ShMonad vault
        uint256 shares = shMonad.deposit{value: amount}(amount, receiver);

        require(shares >= minLpAmount, "Slippage: shares < minLpAmount");

        return shares;
    }

    /// @notice Withdraw assets from ShMonad vault by redeeming shMON shares
    /// @param receiver The account that will receive the assets (Strategy)
    /// @param tokenOut The token to receive (WMON)
    /// @param sharesAmount Amount of shMON shares to redeem
    /// @param minTokenOut Minimum amount of assets to receive (slippage protection)
    /// @return assets The amount of WMON returned
    function withdraw(
        address receiver,
        address tokenOut,
        uint256 sharesAmount,
        uint256 minTokenOut
    ) external returns (uint256) {
        require(tokenOut == wmon, "Token must be WMON");
        require(sharesAmount > 0, "Shares amount must be greater than 0");

        // Transfer shMON shares from sender (Strategy) to this contract
        IERC20(address(shMonad)).transferFrom(msg.sender, address(this), sharesAmount);

        // Redeem from ShMonad - receive native MON to this contract
        uint256 assets = shMonad.redeem(sharesAmount, address(this), address(this));

        require(assets >= minTokenOut, "Slippage: assets < minTokenOut");

        IWMON(wmon).deposit{value: assets}();

        IERC20(wmon).transfer(receiver, assets);

        return assets;
    }

    /// @notice Get comprehensive vault information for a specific account
    /// @param account The account to query vault info for
    /// @return assets Array containing complete info about all underlying tokens
    function vaultInfo(address account)
        external
        view
        override
        returns (VaultInfo[] memory assets)
    {
        assets = new VaultInfo[](1);

        address lpTokenAddr = address(shMonad);  // shMON is the LP token
        address assetTokenAddr = wmon;           // Strategy uses WMON, not native

        uint256 totalLpAmount = IERC20(address(shMonad)).balanceOf(account);

        uint256 totalValueInAsset = shMonad.convertToAssets(totalLpAmount);

        assets[0] = VaultInfo({
            lpToken: lpTokenAddr,
            assetToken: assetTokenAddr,
            lpAmount: totalLpAmount,
            totalValueInAsset: totalValueInAsset
        });

        return assets;
    }

    receive() external payable {}
}

