src/hypervisor/LiteTurboVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "../interfaces/ILBPair.sol";
import "../libraries/ReentrancyGuardUpgradeable.sol";
import "../libraries/math/Uint256x256Math.sol";
import "../libraries/math/LiquidityConfigurations.sol";
import "../libraries/math/SafeCast.sol";
import "./interfaces/ILiteTurboVault.sol";
import "./interfaces/IInvestmentHandler.sol";


/**
 * @title LiteTurboVault
 * @notice Automated liquidity management vault for DLMM pools with buffer management
 * @dev Vault Architecture (3 components):
 *      1. DLMM Liquidity - Active liquidity deployed in DLMM pair bins
 *      2. Buffer - Idle tokens held in vault (for deposits before rebalance)
 *      3. Lending/LSD - (Future) Tokens deployed to lending protocols (not yet implemented)
 * 
 * @dev Workflow:
 *      - Deposit: Tokens transferred to vault buffer, shares minted (no DLMM deployment)
 *      - Rebalance: Remove all DLMM liquidity + buffer → redeploy to new distribution
 *      - Withdraw: Proportional withdrawal from DLMM liquidity + buffer
 */
contract LiteTurboVault is ERC20, ReentrancyGuardUpgradeable, Ownable, ILiteTurboVault {
    using SafeERC20 for IERC20;
    using Uint256x256Math for uint256;
    using SafeCast for uint256;

    // ============ Interfaces ============
    ILBPair public lbPair;
    IERC20 public tokenX;
    IERC20 public tokenY;

    address[] public rewardTokens;

    // ============ Position Tracking ============
    RangeParams private currentRange;
    uint256[] public allBinIds; // All bins with liquidity
    mapping(uint256 => bool) public binTracked; // Track if bin is in allBinIds

    mapping(address => IInvestmentHandler[]) public investmentHandlers; //TokenX/Y => investmentHandler[]

    // ============ Vault Configuration ============
    uint256 public maxTotalSupply;
    uint256 public depositXMax;
    uint256 public depositYMax;
    address public whitelistedAddress;
    address public feeRecipient;
    uint256 public protocolFeeRate; // 10% of fees (in basis points, 1000 = 10%)

    // ============ State Variables ============
    uint256 public binThreshold;
    uint256 public twapInterval;

    // ============ Constants ============
    uint256 constant PRECISION = 1e18;
    uint256 constant BASIS_POINTS = 10000;
    uint256 constant MIN_SHARES = 1000; // Minimum shares to prevent rounding attacks

    bool public paused;

    modifier whenNotPaused() {
        require(!paused, "Paused");
        _;
    }

    /**
     * @notice Constructor for implementation contract (used by Beacon)
     * @dev Disable initializers to prevent implementation from being initialized
     */
    constructor() ERC20("", "") Ownable(msg.sender) {
        _disableInitializers();
    }

    function name() public view virtual override returns (string memory) {
        return "Bean Vault LP";
    }

    function symbol() public view virtual override returns (string memory) {
       return "BLP";
    }

    /**
     * @notice Initialize the vault (called by factory via proxy)
     * @param _lbPair Address of the LBPair to manage
     * @param _owner Owner of the vault
     */
    function initialize(
        address _lbPair,
        address _owner
    ) external initializer {
        require(_lbPair != address(0), "Invalid pair");
        require(_owner != address(0), "Invalid owner");

        __ReentrancyGuard_init();

        // Set pair and tokens
        lbPair = ILBPair(_lbPair);
        tokenX = IERC20(lbPair.getTokenX());
        tokenY = IERC20(lbPair.getTokenY());

        // Transfer ownership
        _transferOwnership(_owner);
    }

    modifier onlyWhitelisted() {
        require(
            msg.sender == whitelistedAddress || 
            whitelistedAddress == address(0), 
            "Not whitelisted"
        );
        _;
    }

    /**
     * @notice Deposit tokens and receive vault shares
     * @param depositX Amount of token X to deposit
     * @param depositY Amount of token Y to deposit
     * @param minShares Minimum shares to receive (slippage protection)
     * @param to Address to receive vault shares
     * @param from Address providing the tokens
     * @return shares Amount of vault shares minted
     */
    function deposit(
        uint256 depositX,
        uint256 depositY,
        uint256 minShares,
        address to,
        address from
    ) external override nonReentrant onlyWhitelisted whenNotPaused returns (uint256 shares) {
        require(depositX > 0 || depositY > 0, "Zero deposit");
        require(depositX <= depositXMax && depositY <= depositYMax, "Exceeds max");
        require(to != address(0) && to != address(this), "Invalid recipient");

        _checkPriceChange(uint40(block.timestamp));
        _settle();

        uint256 _totalSupply = totalSupply();  // Renamed to avoid shadowing
        uint24 activeId = lbPair.getActiveId();     // Active bin id
        uint256 price = lbPair.getPriceFromId(activeId);    // Price of the active bin

        if (depositX > 0) {
            tokenX.safeTransferFrom(from, address(this), depositX);
        }
        if (depositY > 0) {
            tokenY.safeTransferFrom(from, address(this), depositY);
        }

        shares = (depositX * price + depositY << 128);        
        if (_totalSupply > 0) {
            (uint256 poolX, uint256 poolY) = _getTotalAsset();
            uint256 totalPositionValue = poolX * price + (poolY << 128);

            shares = shares * _totalSupply / totalPositionValue;
        }

        require(shares >= MIN_SHARES, "Below minimum");
        require(shares >= minShares, "Slippage: insufficient shares");

        // Mint shares to recipient (tokens stay in vault buffer)
        _mint(to, shares);

        // Verify cap not exceeded
        require(maxTotalSupply == 0 || totalSupply() <= maxTotalSupply, "Cap exceeded");

        emit Deposit(from, to, shares, depositX, depositY);
    }

    /**
     * @notice Withdraw tokens by burning vault shares
     * @param shares Amount of vault shares to burn
     * @param minAmountX Minimum amount of token X to receive (slippage protection)
     * @param minAmountY Minimum amount of token Y to receive (slippage protection)
     * @param to Address to receive tokens
     * @param from Address burning the shares
     * @return amountX Amount of token X withdrawn
     * @return amountY Amount of token Y withdrawn
     */
    function withdraw(
        uint256 shares,
        uint256 minAmountX,
        uint256 minAmountY,
        address to,
        address from
    ) external override nonReentrant whenNotPaused returns (uint256 amountX, uint256 amountY) {
        require(shares > 0, "Zero shares");
        require(to != address(0), "Invalid recipient");
        require(
            from == msg.sender || 
            allowance(from, msg.sender) >= shares, 
            "Not authorized"
        );
        _settle();

        uint256 totalSupplyBefore = totalSupply();

        (uint256 poolX, uint256 poolY) = _getTotalAsset();

        uint256 sharesOfFrom = balanceOf(from);

        amountX = (poolX * shares) / totalSupplyBefore;
        amountY = (poolY * shares) / totalSupplyBefore;

        if (amountX > tokenX.balanceOf(address(this)) || amountY > tokenY.balanceOf(address(this))) {
            uint256 sharesX = (tokenX.balanceOf(address(this)) * shares) / totalSupplyBefore;
            uint256 sharesY = (tokenY.balanceOf(address(this)) * shares) / totalSupplyBefore;
            require(sharesX > 0 && sharesY > 0, "Insufficient shares");
            if (sharesX <= sharesY) {
                amountX = tokenX.balanceOf(address(this));
                amountY = sharesX * amountY / amountX;
                shares = sharesX;
            } else {
                amountY = tokenY.balanceOf(address(this));
                amountX = sharesY * amountX / amountY;
                shares = sharesY;
            }
        } else {
            amountX = amountX;
            amountY = amountY;
        }

        tokenX.safeTransfer(to, amountX);
        tokenY.safeTransfer(to, amountY);

        // Check slippage protection BEFORE burning shares
        require(amountX >= minAmountX && amountY >= minAmountY, "Slippage: insufficient output");

        // Distribute reward tokens proportionally
        for (uint256 i = 0; i < rewardTokens.length; i++) {
            address rewardToken = rewardTokens[i];
            if (rewardToken != address(tokenX) && rewardToken != address(tokenY)) {
                uint256 totalRewardBalance = IERC20(rewardToken).balanceOf(address(this));
                uint256 rewardAmount = (totalRewardBalance * sharesOfFrom) / totalSupplyBefore;
                if (rewardAmount > 0) {
                    IERC20(rewardToken).safeTransfer(to, rewardAmount);
                }
            }
        }

        // Burn shares
        _burn(from, shares);

        emit Withdraw(from, to, shares, amountX, amountY);
    }

    /**
     * @notice Rebalance vault with new distribution (owner only)
     * @param params RebalanceParams struct containing all rebalance configuration
     */
    function rebalance(RebalanceParams calldata params) external override nonReentrant onlyOwner {
        // Validate parameters
        require(params.deltaIds.length == params.distributionX.length && params.deltaIds.length == params.distributionY.length, "Length mismatch");
        require(params.deltaIds.length > 0, "Empty deltaIds");

        // Remove liquidity from ALL bins (including old positions)
        // This returns tokens from DLMM + idle buffer
        (uint256 totalX, uint256 totalY) = _removeLiquidity(BASIS_POINTS);

        // Settle all pending fees and rewards
        _settle();

        // Withdraw all from investment handlers
        if (params.isInvestX) {
            withdrawAllInvestment(address(tokenX));
        }
        if (params.isInvestY) {
            withdrawAllInvestment(address(tokenY));
        }

        // Calculate new range from deltaIds
        uint24 activeId = lbPair.getActiveId();
        int256 minDelta = type(int256).max;
        int256 maxDelta = type(int256).min;

        for (uint256 i = 0; i < params.deltaIds.length; i++) {
            if (params.deltaIds[i] < minDelta) minDelta = params.deltaIds[i];
            if (params.deltaIds[i] > maxDelta) maxDelta = params.deltaIds[i];
        }

        // Validate range
        int256 lowerInt = int256(uint256(activeId)) + minDelta;
        int256 upperInt = int256(uint256(activeId)) + maxDelta;
        require(lowerInt >= 0 && upperInt <= int256(uint256(type(uint24).max)), "Range overflow");

        uint24 lower = uint24(uint256(lowerInt));
        uint24 upper = uint24(uint256(upperInt));

        // Save distribution to storage
        delete currentRange.deltaIds;
        delete currentRange.distributionX;
        delete currentRange.distributionY;

        for (uint256 i = 0; i < params.deltaIds.length; i++) {
            currentRange.deltaIds.push(params.deltaIds[i]);
            currentRange.distributionX.push(params.distributionX[i]);
            currentRange.distributionY.push(params.distributionY[i]);
        }

        // Redeploy liquidity with new distribution
        if (totalX > 0 || totalY > 0) {
            _deployWithDistribution(params.amountX, params.amountY, params.deltaIds, params.distributionX, params.distributionY);
        }

        // Deploy to investment handlers using specified indexes
        if (params.isInvestX && params.investX > 0) {
            require(params.indexInvestX < investmentHandlers[address(tokenX)].length, "Invalid indexInvestX");
            investmentHandlers[address(tokenX)][params.indexInvestX].deposit(address(this), address(tokenX), params.investX, 0);
        }
        if (params.isInvestY && params.investY > 0) {
            require(params.indexInvestY < investmentHandlers[address(tokenY)].length, "Invalid indexInvestY");
            investmentHandlers[address(tokenY)][params.indexInvestY].deposit(address(this), address(tokenY), params.investY, 0);
        }

        // Prepare rebalance info for event
        ILiteTurboVault.RebalanceInfo memory info;
        info.activeId = activeId;

        (uint128 dlmmX, uint128 dlmmY) = _getPositionAmounts();
        info.dlmmX = uint256(dlmmX);
        info.dlmmY = uint256(dlmmY);

        (info.investmentX, info.investmentY) = _getAssetInvestedAmounts();

        info.bufferX = tokenX.balanceOf(address(this));
        info.bufferY = tokenY.balanceOf(address(this));

        info.totalX = info.dlmmX + info.investmentX + info.bufferX;
        info.totalY = info.dlmmY + info.investmentY + info.bufferY;

        emit Rebalance(info);

        // Prepare distribution info for event
        ILiteTurboVault.DistributionInfo memory distInfo;
        distInfo.activeId = activeId;
        distInfo.binIds = new uint24[](params.deltaIds.length);
        distInfo.distributionX = params.distributionX;
        distInfo.distributionY = params.distributionY;

        // Convert deltaIds to absolute binIds
        for (uint256 i = 0; i < params.deltaIds.length; i++) {
            int256 binIdInt = int256(uint256(activeId)) + params.deltaIds[i];
            distInfo.binIds[i] = uint24(uint256(binIdInt));
        }

        emit DistributionUpdated(distInfo);
    }

    /**
     * @notice Compound fees and buffer back into DLMM positions using default distribution
     * @dev Uses the distribution configuration set via setDistribution()
     */
    function compound() external override nonReentrant whenNotPaused {
        require(currentRange.deltaIds.length > 0, "Distribution not set");

        uint256 balanceXBefore = tokenX.balanceOf(address(this));
        uint256 balanceYBefore = tokenY.balanceOf(address(this));
        _settle();
        uint256 balanceXAfter = tokenX.balanceOf(address(this));
        uint256 balanceYAfter = tokenY.balanceOf(address(this));
        uint256 idleX = balanceXAfter - balanceXBefore;
        uint256 idleY = balanceYAfter - balanceYBefore;

        if (idleX > 0 || idleY > 0) {
            _deployWithDistribution(idleX, idleY, currentRange.deltaIds, currentRange.distributionX, currentRange.distributionY);
        }
    }

    /**
     * @notice Owner adds liquidity to DLMM using buffer tokens with default distribution
     * @dev Uses the distribution configuration set via setDistribution()
     * @param amountX Amount of X to add
     * @param amountY Amount of Y to add
     */
    function addLiquidity(
        uint256 amountX,
        uint256 amountY
    ) external override nonReentrant onlyOwner {
        require(currentRange.deltaIds.length > 0, "Distribution not set");
        require(amountX > 0 || amountY > 0, "Zero amounts");

        uint256 balanceX = tokenX.balanceOf(address(this));
        uint256 balanceY = tokenY.balanceOf(address(this));

        require(amountX <= balanceX && amountY <= balanceY, "Insufficient balance");

        uint24 activeId = lbPair.getActiveId();

        bytes32[] memory liquidityConfigs = new bytes32[](currentRange.deltaIds.length);
        uint24[] memory binIds = new uint24[](currentRange.deltaIds.length);

        for (uint256 i = 0; i < currentRange.deltaIds.length; i++) {
            int256 _id = int256(uint256(activeId)) + currentRange.deltaIds[i];
            require(_id >= 0 && uint256(_id) <= type(uint24).max, "Id overflow");

            binIds[i] = uint24(uint256(_id));
            liquidityConfigs[i] = LiquidityConfigurations.encodeParams(
                uint64(currentRange.distributionX[i]),
                uint64(currentRange.distributionY[i]),
                binIds[i]
            );

            if (!binTracked[binIds[i]]) {
                allBinIds.push(binIds[i]);
                binTracked[binIds[i]] = true;
            }
        }

        if (amountX > 0) {
            tokenX.safeTransfer(address(lbPair), amountX);
        }
        if (amountY > 0) {
            tokenY.safeTransfer(address(lbPair), amountY);
        }

        lbPair.mint(address(this), liquidityConfigs, address(this), 0);
    }

    function removeLiquidity(uint256 percentage) external override nonReentrant onlyOwner returns (uint256 amountX, uint256 amountY) {
        return _removeLiquidity(percentage);
    }

    /**
     * @notice Deposit to a specific investment handler by index
     * @param assetToken Token to deposit (tokenX or tokenY)
     * @param amount Amount to deposit
     * @param minLpAmount Minimum LP amount to receive
     * @param handlerIndex Index of the handler in investmentHandlers array
     */
    function invest(
        address assetToken,
        uint256 amount,
        uint256 minLpAmount,
        uint256 handlerIndex
    ) external override nonReentrant onlyOwner returns (uint256 lpAmount) {
        require(amount > 0, "Amount must be greater than 0");
        require(assetToken == address(tokenX) || assetToken == address(tokenY), "Invalid token");
        require(handlerIndex < investmentHandlers[assetToken].length, "Invalid handler index");

        lpAmount = investmentHandlers[assetToken][handlerIndex].deposit(address(this), assetToken, amount, minLpAmount);
    }

    /**
     * @notice Withdraw from a specific investment handler by index
     * @param assetToken Token to withdraw (tokenX or tokenY)
     * @param lpAmount LP amount to burn
     * @param minAmount Minimum token amount to receive
     * @param handlerIndex Index of the handler in investmentHandlers array
     */
    function divest(
        address assetToken,
        uint256 lpAmount,
        uint256 minAmount,
        uint256 handlerIndex
    ) external override nonReentrant onlyOwner returns (uint256 amount) {
        require(assetToken == address(tokenX) || assetToken == address(tokenY), "Invalid token");
        require(handlerIndex < investmentHandlers[assetToken].length, "Invalid handler index");

        amount = investmentHandlers[assetToken][handlerIndex].withdraw(address(this), assetToken, lpAmount, minAmount);
    }

    /**
     * @notice Withdraw all LP tokens of a specific asset from ALL investment handlers
     * @param token The token address to withdraw (tokenX or tokenY)
     * @return amount Total amount withdrawn
     */
    function withdrawAllInvestment(address token) internal returns (uint256 amount) {
        require(token == address(tokenX) || token == address(tokenY), "Invalid token");

        IInvestmentHandler[] memory handlers = investmentHandlers[token];

        // Loop through all handlers for this token
        for (uint256 i = 0; i < handlers.length; i++) {
            IInvestmentHandler.VaultInfo[] memory assets = handlers[i].vaultInfo(address(this));

            // Withdraw all LP tokens of this token from this handler
            for (uint256 j = 0; j < assets.length; j++) {
                if (assets[j].assetToken == token && assets[j].lpAmount > 0) {
                    amount += handlers[i].withdraw(address(this), token, assets[j].lpAmount, 0);
                }
            }
        }
    }

    // ============ View Functions ============

    /**
     * @notice Get comprehensive vault asset breakdown
     * @return assets VaultAssets struct containing all asset information
     */
    function getVaultAssets() public view override returns (ILiteTurboVault.VaultAssets memory assets) {
        // 1. DLMM liquidity
        (uint128 posX, uint128 posY) = _getPositionAmounts();
        assets.dlmmX = uint256(posX);
        assets.dlmmY = uint256(posY);

        // 2. Buffer (idle tokens)
        assets.bufferX = tokenX.balanceOf(address(this));
        assets.bufferY = tokenY.balanceOf(address(this));

        // 3. Investment handlers
        (assets.investedX, assets.investedY) = _getAssetInvestedAmounts();

        // 4. Pending fees (after protocol cut)
        (uint128[] memory feesX, uint128[] memory feesY) = lbPair.getPendingFees(allBinIds, address(this));

        // Sum all pending fees
        for (uint256 i = 0; i < feesX.length; i++) {
            assets.pendingFeesX += uint256(feesX[i]);
            assets.pendingFeesY += uint256(feesY[i]);
        }

        // 5. Collected rewards
        // Note: If reward token is X/Y, it's already included in bufferX/Y
        // So collectedRewardsX/Y = 0 (to avoid double counting)

        // 6. Pending rewards (call lbPair directly, not yet collected)
        if (allBinIds.length > 0) {
            uint256[] memory ids = new uint256[](allBinIds.length);
            for (uint256 i = 0; i < allBinIds.length; i++) {
                ids[i] = uint256(allBinIds[i]);
            }

            uint128[][] memory rewards = lbPair.getPendingRewards(ids, address(this));

            // Find max number of rewarders
            uint256 numRewarders = 0;
            for (uint256 i = 0; i < rewards.length; i++) {
                if (rewards[i].length > numRewarders) {
                    numRewarders = rewards[i].length;
                }
            }

            // Sum pending rewards for X and Y tokens only
            for (uint256 j = 0; j < numRewarders; j++) {
                (address rewardToken, ) = lbPair.getInfoRewarder(j);

                if (rewardToken == address(tokenX)) {
                    for (uint256 i = 0; i < rewards.length; i++) {
                        if (j < rewards[i].length) {
                            assets.pendingRewardsX += uint256(rewards[i][j]);
                        }
                    }
                } else if (rewardToken == address(tokenY)) {
                    for (uint256 i = 0; i < rewards.length; i++) {
                        if (j < rewards[i].length) {
                            assets.pendingRewardsY += uint256(rewards[i][j]);
                        }
                    }
                }
            }
        }

        // Calculate totals (collectedRewards already in bufferX/Y)
        assets.totalX = assets.dlmmX + assets.bufferX + assets.investedX + assets.pendingFeesX + assets.pendingRewardsX;
        assets.totalY = assets.dlmmY + assets.bufferY + assets.investedY + assets.pendingFeesY + assets.pendingRewardsY;
    }

    /**
     * @notice Get user's share value in underlying tokens
     * @param user Address of the user
     * @return amountX Amount of tokenX user can withdraw
     * @return amountY Amount of tokenY user can withdraw
     */
    function getUserBalance(address user) external view override returns (
        uint256 amountX,
        uint256 amountY
    ) {
        uint256 userShares = balanceOf(user);
        uint256 totalSupply = totalSupply();

        if (userShares == 0 || totalSupply == 0) {
            return (0, 0);
        }

        // Get comprehensive vault assets (1 call instead of multiple)
        ILiteTurboVault.VaultAssets memory assets = getVaultAssets();

        // Calculate user's proportional share
        // Note: totalX/totalY already includes DLMM + buffer + invested + fees + rewards
        amountX = (assets.totalX * userShares) / totalSupply;
        amountY = (assets.totalY * userShares) / totalSupply;
    }

    /**
     * @notice Get current range distribution configuration
     * @return deltaIds Array of delta IDs from active bin
     * @return distributionX Distribution for token X
     * @return distributionY Distribution for token Y
     */
    function getCurrentRange() external view returns (
        int256[] memory deltaIds,
        uint256[] memory distributionX,
        uint256[] memory distributionY
    ) {
        return (currentRange.deltaIds, currentRange.distributionX, currentRange.distributionY);
    }

    /**
     * @notice Settle pending fees and rewards
     */
    function _settle() private {
        _collectAllFees();
        _collectRewards();
    }

    /**
     * @notice Collect rewards from all bins
     */
    function _collectRewards() private {
        if (allBinIds.length == 0) return;

        uint256[] memory binIds = new uint256[](allBinIds.length);
        for (uint256 i = 0; i < allBinIds.length; i++) {
            binIds[i] = uint256(allBinIds[i]);
        }

        // Collect rewards from LBPair
        uint128[][] memory rewards = lbPair.collectRewards(binIds, address(this));

        // Find max number of rewarders across all bins
        uint256 numRewarders = 0;
        for (uint256 i = 0; i < rewards.length; i++) {
            if (rewards[i].length > numRewarders) {
                numRewarders = rewards[i].length;
            }
        }

        // Process each rewarder index
        for (uint256 j = 0; j < numRewarders; j++) {
            // Get reward token address for this rewarder index
            (address rewardToken, ) = lbPair.getInfoRewarder(j);

            if (rewardToken != address(0)) {
                // Add to rewardTokens array if not already tracked
                bool isTracked = false;
                for (uint256 k = 0; k < rewardTokens.length; k++) {
                    if (rewardTokens[k] == rewardToken) {
                        isTracked = true;
                        break;
                    }
                }
                if (!isTracked) {
                    rewardTokens.push(rewardToken);
                }

                // Rewards are automatically accumulated in contract balance
            }
        }
    }

        /**
     * @notice Collect fees from all bins and transfer to feeRecipient
     */
    function _collectAllFees() private {
        if (allBinIds.length == 0 || feeRecipient == address(0)) return;

            // Collect fees directly to this contract first
        (uint128 feesX, uint128 feesY) = lbPair.collectFees(allBinIds, address(this));

        if (feesX > 0 || feesY > 0) {
            // Calculate protocol fees
            uint256 protocolX = (uint256(feesX) * protocolFeeRate) / BASIS_POINTS;
            uint256 protocolY = (uint256(feesY) * protocolFeeRate) / BASIS_POINTS;

            // Prepare arrays for event
            address[] memory tokens = new address[](2);
            uint256[] memory amounts = new uint256[](2);
            tokens[0] = address(tokenX);
            tokens[1] = address(tokenY);
            amounts[0] = protocolX;
            amounts[1] = protocolY;

                // Transfer protocol fees to recipient
            if (protocolX > 0) {
                tokenX.safeTransfer(feeRecipient, protocolX);
            }
            if (protocolY > 0) {
                tokenY.safeTransfer(feeRecipient, protocolY);
            }

            emit ProtocolFeesCollected(feeRecipient, tokens, amounts);
        }
    }

    /**
     * @notice Remove liquidity from all bins with percentage precision
     * @param percentage Percentage in basis points (10000 = 100%)
     * @return amountX Amount of token X withdrawn
     * @return amountY Amount of token Y withdrawn
     */
    function _removeLiquidity(uint256 percentage) private returns (uint256 amountX, uint256 amountY){
        if (allBinIds.length == 0) {
            return (0, 0);
        }

        require(percentage <= BASIS_POINTS, "Percentage too high");

        uint256[] memory ids = new uint256[](allBinIds.length);
        uint256[] memory amounts = new uint256[](allBinIds.length);
        uint256 count = 0;

        // Collect all bins with liquidity
        for (uint256 i = 0; i < allBinIds.length; i++) {
            uint256 binId = allBinIds[i];
            uint256 balance = lbPair.balanceOf(address(this), binId) * percentage / BASIS_POINTS;

            if (balance > 0) {
                ids[count] = binId;
                amounts[count] = balance;
                count++;
            }

            // If removing 100%, clear bin tracking
            if (percentage == BASIS_POINTS) {
                binTracked[binId] = false;
            }
        }

        if (count > 0) {

            assembly {
                mstore(ids, count)
                mstore(amounts, count)
            }

            // Burn all liquidity
            bytes32[] memory withdrawn = lbPair.burn(
                address(this),
                address(this),
                ids,
                amounts
            );

            // Sum withdrawn amounts
            for (uint256 i = 0; i < withdrawn.length; i++) {
                (uint128 x, uint128 y) = _decodeBytes32(withdrawn[i]);
                amountX += x;
                amountY += y;
            }
        }

        // If removing 100%, clear allBinIds array
        if (percentage == BASIS_POINTS) {
            delete allBinIds;
        }
    }

    /**
     * @notice Deploy liquidity with specified distribution
     */
    function _deployWithDistribution(
        uint256 amountX,
        uint256 amountY,
        int256[] memory _deltaIds,
        uint256[] memory _distributionX,
        uint256[] memory _distributionY
    ) private {
        if (amountX == 0 && amountY == 0) return;

        uint24 activeId = lbPair.getActiveId();

        // Build liquidityConfigs from distribution (like LBRouter)
        bytes32[] memory liquidityConfigs = new bytes32[](_deltaIds.length);
        uint24[] memory binIds = new uint24[](_deltaIds.length);

        for (uint256 i = 0; i < _deltaIds.length; i++) {
            int256 _id = int256(uint256(activeId)) + _deltaIds[i];
            require(_id >= 0 && uint256(_id) <= type(uint24).max, "Id overflow");

            binIds[i] = uint24(uint256(_id));
            liquidityConfigs[i] = LiquidityConfigurations.encodeParams(
                uint64(_distributionX[i]),
                uint64(_distributionY[i]),
                binIds[i]
            );

            // Track new bins
            if (!binTracked[binIds[i]]) {
                allBinIds.push(binIds[i]);
                binTracked[binIds[i]] = true;
            }
        }

        // Transfer tokens to pair FIRST (LBPair detects balance increase)
        if (amountX > 0) {
            tokenX.safeTransfer(address(lbPair), amountX);
        }
        if (amountY > 0) {
            tokenY.safeTransfer(address(lbPair), amountY);
        }

        // Call mint (pair detects balance increase and mints LP tokens)
        lbPair.mint(address(this), liquidityConfigs, address(this), 0);
    }

    /**
     * @notice Check if price change is within acceptable threshold
     * @dev Protects against price manipulation by checking bins crossed in TWAP interval
     * @param lookupTimestamp Current timestamp to check from
     */
    function _checkPriceChange(uint40 lookupTimestamp) private view {
        require(twapInterval > 0 && binThreshold > 0, "Not configured");

        uint40 pastTimestamp = lookupTimestamp - twapInterval.safe40();

        (,, uint64 cumulativeBinCrossed) = lbPair.getOracleSampleAt(lookupTimestamp);
        (,, uint64 cumulativeBinCrossedPast) = lbPair.getOracleSampleAt(pastTimestamp);

        // Cumulative values should only increase, if not it means data issue
        require(cumulativeBinCrossed >= cumulativeBinCrossedPast, "Invalid oracle data");

        uint256 binsCrossed = cumulativeBinCrossed - cumulativeBinCrossedPast;

        require(binsCrossed <= binThreshold, "Price change too large");
    }

    function _getPositionAmounts() private view returns (uint128 totalAmountX, uint128 totalAmountY) {
        for (uint256 i = 0; i < allBinIds.length; i++) {
            uint256 binId = allBinIds[i];
            (uint128 binReserveX, uint128 binReserveY) = lbPair.getBin(binId.safe24());
            (uint128 amountXOutFromBin, uint128 amountYOutFromBin) = _getAmountOutOfBin(binReserveX, binReserveY, lbPair.balanceOf(address(this), binId), lbPair.totalSupply(binId));

            totalAmountX += amountXOutFromBin;
            totalAmountY += amountYOutFromBin;
        }
        return (totalAmountX, totalAmountY);
    }

    function _getAmountOutOfBin(uint256 binReserveX, uint256 binReserveY, uint256 amountToBurn, uint256 binTotalSupply)
        private
        pure
        returns (uint128 amountXOutFromBin, uint128 amountYOutFromBin)
    {
        if (binReserveX > 0) {
            amountXOutFromBin = (amountToBurn.mulDivRoundDown(binReserveX, binTotalSupply)).safe128();
        }

        if (binReserveY > 0) {
            amountYOutFromBin = (amountToBurn.mulDivRoundDown(binReserveY, binTotalSupply)).safe128();
        }
    }

    function _getTotalAsset() private view returns (uint256 amountX, uint256 amountY) {
        (uint128 totalAmountX, uint128 totalAmountY) = _getPositionAmounts();
        (uint256 assetsInvestedX, uint256 assetsInvestedY) = _getAssetInvestedAmounts();
        amountX = uint256(totalAmountX) + tokenX.balanceOf(address(this)) + assetsInvestedX;
        amountY = uint256(totalAmountY) + tokenY.balanceOf(address(this)) + assetsInvestedY;
    }

    function _getAssetInvestedAmounts() private view returns (uint256 assetsInvestedX, uint256 assetsInvestedY) {
        // Loop through all handlers for tokenX
        IInvestmentHandler[] memory handlersX = investmentHandlers[address(tokenX)];
        for (uint256 i = 0; i < handlersX.length; i++) {
            IInvestmentHandler.VaultInfo[] memory assets = handlersX[i].vaultInfo(address(this));
            for (uint256 j = 0; j < assets.length; j++) {
                if (assets[j].assetToken == address(tokenX)) {
                    assetsInvestedX += assets[j].totalValueInAsset;
                }
            }
        }

        // Loop through all handlers for tokenY
        IInvestmentHandler[] memory handlersY = investmentHandlers[address(tokenY)];
        for (uint256 i = 0; i < handlersY.length; i++) {
            IInvestmentHandler.VaultInfo[] memory assets = handlersY[i].vaultInfo(address(this));
            for (uint256 j = 0; j < assets.length; j++) {
                if (assets[j].assetToken == address(tokenY)) {
                    assetsInvestedY += assets[j].totalValueInAsset;
                }
            }
        }

        return (assetsInvestedX, assetsInvestedY);
    }

    function _decodeBytes32(bytes32 data) private pure returns (uint128 x, uint128 y) {
        x = uint128(uint256(data >> 128));
        y = uint128(uint256(data));
    }

    // ============ Admin Functions ============

    function setFeeRecipient(address _feeRecipient) external override onlyOwner {
        feeRecipient = _feeRecipient;
        emit FeeRecipientUpdated(feeRecipient, _feeRecipient);
    }

    function setProtocolFeeRate(uint256 _rate) external override onlyOwner {
        require(_rate <= 5000, "Fee too high");
        uint256 oldRate = protocolFeeRate;
        protocolFeeRate = _rate;
        emit ProtocolFeeRateUpdated(oldRate, _rate);
    }

    function setWhitelist(address _address) external override onlyOwner {
        whitelistedAddress = _address;
    }

    function setDepositMax(uint256 _xMax, uint256 _yMax) external override onlyOwner {
        depositXMax = _xMax;
        depositYMax = _yMax;
    }

    function setMaxTotalSupply(uint256 _max) external override onlyOwner {
        maxTotalSupply = _max;
    }

    function setBinThreshold(uint256 _threshold) external override onlyOwner {
        binThreshold = _threshold;
    }

    function setTwapInterval(uint256 _interval) external override onlyOwner {
        twapInterval = _interval;
    }

    /**
     * @notice Set default distribution configuration
     * @param _deltaIds Offsets from active bin (e.g. [-5, -4, ..., 0, ..., 4, 5])
     * @param _distributionX Distribution for X (sum must = 1e18)
     * @param _distributionY Distribution for Y (sum must = 1e18)
     */
    function setDistribution(
        int256[] memory _deltaIds,
        uint256[] memory _distributionX,
        uint256[] memory _distributionY
    ) external override onlyOwner {
        require(_deltaIds.length == _distributionX.length && _deltaIds.length == _distributionY.length, "Length mismatch");
        require(_deltaIds.length > 0, "Empty deltaIds");

        // Clear old distribution
        delete currentRange.deltaIds;
        delete currentRange.distributionX;
        delete currentRange.distributionY;

        // Save new distribution
        for (uint256 i = 0; i < _deltaIds.length; i++) {
            currentRange.deltaIds.push(_deltaIds[i]);
            currentRange.distributionX.push(_distributionX[i]);
            currentRange.distributionY.push(_distributionY[i]);
        }

        // emit DistributionUpdated(_deltaIds, _distributionX, _distributionY);
    }

    /**
     * @notice Add an investment handler for a specific token
     * @param token Token address (tokenX or tokenY)
     * @param handler Investment handler address to add
     */
    function addInvestmentHandler(address token, address handler) external override onlyOwner {
        require(token == address(tokenX) || token == address(tokenY), "Invalid token");
        require(handler != address(0), "Invalid handler");
        require(handler != address(lbPair), "Cannot be LBPair");
        require(handler != address(this), "Cannot be vault");

        // Check if handler already exists
        IInvestmentHandler[] storage handlers = investmentHandlers[token];
        for (uint256 i = 0; i < handlers.length; i++) {
            require(address(handlers[i]) != handler, "Handler already exists");
        }

        handlers.push(IInvestmentHandler(handler));
        emit InvestmentHandlerAdded(token, handler, handlers.length - 1);
    }

    /**
     * @notice Remove an investment handler by index
     * @param token Token address (tokenX or tokenY)
     * @param index Index of the handler to remove
     */
    function removeInvestmentHandler(address token, uint256 index) external override onlyOwner {
        require(token == address(tokenX) || token == address(tokenY), "Invalid token");
        IInvestmentHandler[] storage handlers = investmentHandlers[token];
        require(index < handlers.length, "Invalid index");

        // Check that handler has no funds
        IInvestmentHandler.VaultInfo[] memory assets = handlers[index].vaultInfo(address(this));
        for (uint256 i = 0; i < assets.length; i++) {
            require(assets[i].lpAmount == 0, "Handler has funds");
        }

        address removedHandler = address(handlers[index]);

        // Remove by swapping with last and popping
        handlers[index] = handlers[handlers.length - 1];
        handlers.pop();

        emit InvestmentHandlerRemoved(token, removedHandler, index);
    }

    function setPaused(bool _paused) external override onlyOwner {
        paused = _paused;
    }
}

