// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.20;

struct AccountSnapshot {
    address asset;
    address underlying;
    uint8 decimals;
    bool isCollateral;
    uint256 collateralPosted;
    uint256 debtBalance;
}

interface ICToken {
    /// @notice Starts a cToken market, executed via marketManager.
    /// @dev This initial mint is a failsafe against rounding exploits,
    ///      although, we protect against them in many ways,
    ///      better safe than sorry.
    /// @param by The account initializing deposits.
    function initializeDeposits(address by) external returns (bool);

    /// @notice Returns the decimals of the cToken.
    /// @dev We pull directly from underlying incase its a proxy contract,
    ///      and changes decimals on us.
    /// @return The number of decimals for this cToken,
    ///         matching the underlying token.
    function decimals() external view returns (uint8);

    function name() external view returns (string memory);
    function symbol() external view returns (string memory);

    /// @notice Returns whether the underlying token can be borrowed.
    /// @dev true = Borrowable; false = Not Borrowable.
    /// @return Whether this token is borrowable or not.
    function isBorrowable() external view returns (bool);

    /// @notice The token balance of an account.
    /// @dev Account address => account token balance.
    /// @param account The address of the account to query token balance for.
    function balanceOf(address account) external view returns (uint256);

    /// @notice Returns the address of the underlying asset.
    /// @return The address of the underlying asset.
    function asset() external view returns (address);

    /// @notice Updates pending assets and returns a snapshot of the cToken
    ///         and `account` data.
    /// @dev Used by marketManager to more efficiently perform
    ///      liquidity checks.
    /// @return result The snapshot of the cToken and `account` data.
    function getSnapshotUpdated(
        address account
    ) external returns (AccountSnapshot memory result);

    /// @notice Get a snapshot of `account` data in this Curvance token.
    /// @dev NOTE: Does not accrue pending assets as part of the call.
    /// @param account The address of the account to snapshot.
    /// @return The account snapshot of `account`.
    function getSnapshot(
        address account
    ) external view returns (AccountSnapshot memory);

    /// @notice Total number of cTokens in circulation.
    function totalSupply() external view returns (uint256);

    /// @notice Returns the total amount of assets held by the market.
    /// @return The total amount of assets held by the market.
    function totalAssets() external view returns (uint256);

    /// @notice Returns the amount of assets that would be exchanged
    ///         by the vault for `shares` provided.
    /// @param shares The number of shares to theoretically use
    ///               for conversion to assets.
    /// @return The number of assets a user would receive for converting
    ///         `shares`.
    function convertToAssets(uint256 shares) external view returns (uint256);

    /// @notice Updates pending assets and returns the up-to-date exchange
    ///         rate from the underlying to the BorrowableCToken.
    /// @dev Oracle Manager calculates cToken value from this exchange rate.
    /// @return The share -> asset exchange rate, in `WAD`.
    function exchangeRateUpdated() external returns (uint256) ;

    /// @notice Returns the up-to-date exchange rate from the underlying to
    ///         the BorrowableCToken.
    /// @dev Oracle Manager calculates cToken value from this exchange rate.
    /// @return The share -> asset exchange rate, in `WAD`.
    function exchangeRate() external view returns (uint256);

    /// @notice Caller deposits `assets` into the market and `receiver`
    ///         receives shares.
    /// @param assets The amount of the underlying assets to deposit.
    /// @param receiver The account that should receive the shares.
    /// @return shares The amount of shares received by `receiver`.
    function deposit(
        uint256 assets,
        address receiver
    ) external returns (uint256 shares);

    /// @notice Caller deposits `assets` into the market, `receiver` receives
    ///         shares, and collateralization of `assets` is enabled.
    /// @dev The caller must be depositing for themselves, or be managing
    ///      their position through a Position Manager contract.
    ///      If the caller is not approved to collateralize the function will
    ///      simply deposit assets on behalf of `receiver`.
    /// @param assets The amount of the underlying assets to deposit.
    /// @param receiver The account that should receive the shares.
    /// @return shares The amount of shares received by `receiver`.
    function depositAsCollateral(
        uint256 assets,
        address receiver
    ) external returns (uint256 shares);

    /// @notice Caller deposits `assets` into the market, `receiver` receives
    ///         shares, and collateralization of `assets` is enabled.
    /// @dev Requires that `receiver` approves the caller prior to
    ///      collateralize on their behalf.
    ///      NOTE: Be careful who you approve here!
    ///      They can delay redemption of assets through repeated
    ///      collateralization preventing withdrawal.
    ///      If the caller is not approved to collateralize the function will
    ///      simply deposit assets on behalf of `receiver`.
    /// @param assets The amount of the underlying assets to deposit.
    /// @param receiver The account that should receive the shares.
    /// @return shares The amount of shares received by `receiver`.
    function depositAsCollateralFor(
        uint256 assets,
        address receiver
    ) external returns (uint256 shares);

    /// @notice Withdraws assets, quoted in `shares` from the market,
    ///         and burns `owner` shares.
    /// @dev Does not force collateral to be withdrawn.
    /// @param shares The amount of shares to be redeemed.
    /// @param receiver The account that should receive the assets.
    /// @param owner The account that will burn their shares to withdraw
    ///              assets.
    /// @return assets The amount of assets redeemed by `owner`.
    function redeem(
        uint256 shares,
        address receiver,
        address owner
    ) external returns (uint256 assets);

    /// @notice Withdraws assets, quoted in `shares` from the market,
    ///         and burns `owner` shares, sending assets to `receiver`.
    /// @dev Does not force collateral to be withdrawn.
    /// @param shares The amount of shares to redeemed.
    /// @param receiver The account that should receive the assets.
    /// @param owner The account that will burn their shares to withdraw
    ///              assets.
    /// @return assets The amount of assets redeemed by `owner` and sent to
    ///                `receiver`.
    function redeemFor(
        uint256 shares,
        address receiver,
        address owner
    ) external returns (uint256 assets);

    /// @notice Caller withdraws assets from the market and burns their
    ///         shares, on behalf of `owner`.
    /// @dev Forces collateral to be withdrawn from `owner` collateralPosted.
    /// @param shares The amount of shares to redeemed.
    /// @param receiver The account that should receive the assets.
    /// @param owner The account that will burn their shares to withdraw
    ///              assets.
    /// @return assets The amount of assets redeemed by `owner` and sent to
    ///                `receiver`.
    function redeemCollateralFor(
        uint256 shares,
        address receiver,
        address owner
    ) external returns (uint256 assets);

    /// @notice Amount of tokens that has been posted as collateral,
    ///         in shares.
    function marketCollateralPosted() external view returns (uint256);

    /// @notice Shares of this token that an account has posted as collateral.
    /// @param account The address of the account to check collateral posted
    ///                of.
    function collateralPosted(address account) external view returns (uint256);

    /// @notice Transfers tokens from `account` to `liquidator`.
    /// @dev Will fail unless called by a cToken during the process
    ///      of liquidation.
    /// @param shares An array containing the number of cToken shares
    ///               to seize.
    /// @param liquidator The account receiving seized cTokens.
    /// @param accounts An array containing the accounts having
    ///                 collateral seized.
    function seize(
        uint256[] calldata shares,
        address liquidator,
        address[] calldata accounts
    ) external;

    /// @notice Allows users to simulate the effects of their deposit at
    ///         the current block.
    /// @param assets The number of assets to preview a deposit call.
    /// @return The shares received for depositing `assets`.
    function previewDeposit(uint256 assets) external view returns (uint256);
}

src/hypervisor/interfaces/ILiteTurboVaul.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface ILiteTurboVault {

    struct RangeParams {
        int256[] deltaIds;
        uint256[] distributionX;
        uint256[] distributionY;
    }
    struct RebalanceParams {
        uint256 amountX;           // Amount of X to deploy to DLMM
        uint256 amountY;           // Amount of Y to deploy to DLMM
        uint256 investX;           // Amount of X to invest in handler
        uint256 investY;           // Amount of Y to invest in handler
        int256[] deltaIds;         // Offsets from active bin
        uint256[] distributionX;   // Distribution for X
        uint256[] distributionY;   // Distribution for Y
        uint256 indexInvestX;      // Handler index for tokenX
        uint256 indexInvestY;      // Handler index for tokenY
        bool isInvestX;            // Whether to invest X
        bool isInvestY;            // Whether to invest Y
    }

    struct VaultAssets {
        uint256 dlmmX;                      // X in DLMM positions
        uint256 dlmmY;                      // Y in DLMM positions
        uint256 bufferX;                    // X in vault buffer (idle, includes collected rewards)
        uint256 bufferY;                    // Y in vault buffer (idle, includes collected rewards)
        uint256 investedX;                  // X in investment handlers
        uint256 investedY;                  // Y in investment handlers
        uint256 pendingFeesX;               // Pending fees in X (after protocol cut, not yet collected)
        uint256 pendingFeesY;               // Pending fees in Y (after protocol cut, not yet collected)
        uint256 pendingRewardsX;            // Pending rewards in X (not yet collected)
        uint256 pendingRewardsY;            // Pending rewards in Y (not yet collected)
        uint256 totalX;                     // Total X (sum of all above)
        uint256 totalY;                     // Total Y (sum of all above)
    }

    /**
     * @notice Struct containing rebalance information for event emission
     */
    struct RebalanceInfo {
        uint24 activeId;                    // Current active bin ID
        uint256 totalX;                     // Total tokenX in vault
        uint256 totalY;                     // Total tokenY in vault
        uint256 dlmmX;                      // TokenX in DLMM positions
        uint256 dlmmY;                      // TokenY in DLMM positions
        uint256 investmentX;                // TokenX in investment handlers
        uint256 investmentY;                // TokenY in investment handlers
        uint256 bufferX;                    // TokenX in buffer (idle)
        uint256 bufferY;                    // TokenY in buffer (idle)
    }

    /**
     * @notice Struct containing distribution information for DLMM positions
     */
    struct DistributionInfo {
        uint24[] binIds;                    // All bin IDs with liquidity
        uint256[] distributionX;            // Distribution for X per bin
        uint256[] distributionY;            // Distribution for Y per bin
        uint256 activeId;                   // Current active bin ID
    }


    function initialize(
        address _lbPair,
        address _owner
    ) external;

    function deposit(
        uint256 depositX,
        uint256 depositY,
        uint256 minShares,
        address to,
        address from
    ) external returns (uint256 shares);

    function withdraw(
        uint256 shares,
        uint256 minAmountX,
        uint256 minAmountY,
        address to,
        address from
    ) external returns (uint256 amountX, uint256 amountY);

    function rebalance(RebalanceParams calldata params) external;

    function compound() external;

    function addLiquidity(uint256 amountX, uint256 amountY) external;

    /**
     * @notice Remove liquidity from DLMM with percentage precision
     * @param percentage Percentage in basis points (10000 = 100%)
     * @return amountX Amount of token X withdrawn
     * @return amountY Amount of token Y withdrawn
     */
    function removeLiquidity(uint256 percentage) external returns (uint256 amountX, uint256 amountY); 

    /**
     * @notice Deposit tokens to an investment handler
     * @param assetToken Token address to invest (tokenX or tokenY)
     * @param amount Amount of tokens to invest
     * @param minLpAmount Minimum LP amount to receive (slippage protection)
     * @param handlerIndex Index of the investment handler in the array
     * @return lpAmount Amount of LP tokens received
     */
    function invest(
        address assetToken,
        uint256 amount,
        uint256 minLpAmount,
        uint256 handlerIndex
    ) external returns (uint256 lpAmount);

    /**
     * @notice Withdraw tokens from an investment handler
     * @param assetToken Token address to withdraw (tokenX or tokenY)
     * @param lpAmount Amount of LP tokens to burn
     * @param minAmount Minimum amount of tokens to receive (slippage protection)
     * @param handlerIndex Index of the investment handler in the array
     * @return amount Amount of tokens withdrawn
     */
    function divest(
        address assetToken,
        uint256 lpAmount,
        uint256 minAmount,
        uint256 handlerIndex
    ) external returns (uint256 amount);

    // ============ View Functions ============
    function getVaultAssets() external view returns (VaultAssets memory assets);

    function getUserBalance(address user) external view returns (
        uint256 amountX,
        uint256 amountY
    );

    function getCurrentRange() external view returns (
        int256[] memory deltaIds,
        uint256[] memory distributionX,
        uint256[] memory distributionY
    );

    // ============ Admin Functions ============
    function setPaused(bool _paused) external;
    function setFeeRecipient(address _feeRecipient) external;
    function setProtocolFeeRate(uint256 _rate) external;

    /**
     * @notice Set whitelisted address for deposits
     * @param _address Address to whitelist (or address(0) to disable whitelist)
     */
    function setWhitelist(address _address) external; // has modifier onlyWhitelisted

    function setDepositMax(uint256 _xMax, uint256 _yMax) external;
    function setMaxTotalSupply(uint256 _max) external;
    function setBinThreshold(uint256 _threshold) external;

    function setTwapInterval(uint256 _interval) external;

    function setDistribution(
        int256[] memory _deltaIds,
        uint256[] memory _distributionX,
        uint256[] memory _distributionY
    ) external;

    function addInvestmentHandler(address token, address handler) external;
    function removeInvestmentHandler(address token, uint256 index) external;

    // ============ Events ============
    event Deposit(address indexed from, address indexed to, uint256 shares, uint256 amountX, uint256 amountY);
    event Withdraw(address indexed from, address indexed to, uint256 shares, uint256 amountX, uint256 amountY);

    /**
     * @notice Emitted when vault is rebalanced
     * @param info RebalanceInfo struct containing all rebalance details
     */
    event Rebalance(RebalanceInfo info);

    /**
     * @notice Emitted when protocol fees are collected
     * @param recipient Address receiving the fees
     * @param tokens Array of token addresses
     * @param amounts Array of fee amounts corresponding to each token
     */
    event ProtocolFeesCollected(address indexed recipient, address[] tokens, uint256[] amounts);

    /**
     * @notice Emitted when DLMM distribution is updated
     * @param info DistributionInfo struct containing all distribution details
     */
    event DistributionUpdated(DistributionInfo info);

    event ProtocolFeeRateUpdated(uint256 oldRate, uint256 newRate);
    event FeeRecipientUpdated(address indexed oldRecipient, address indexed newRecipient);
    event InvestmentHandlerAdded(address indexed token, address indexed handler, uint256 index);
    event InvestmentHandlerRemoved(address indexed token, address indexed handler, uint256 index);
}

