// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Ownable2Step, Ownable} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {BeaconProxy} from "@openzeppelin/contracts/proxy/beacon/BeaconProxy.sol";
import {ILBPair} from "../interfaces/ILBPair.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./interfaces/IVaultFactory.sol";
import "./interfaces/ILiteTurboVault.sol";

/**
 * @title VaultFactory
 * @notice Factory contract to deploy LiteTurboVault instances using Beacon Proxy pattern
 * @dev Similar to LBFactory but for vault management
 */
contract VaultFactory is Ownable2Step, IVaultFactory {

    // ============ State Variables ============

    address private _vaultBeacon;

    ILiteTurboVault[] private _allVaults;

    mapping(address => ILiteTurboVault) private _vaultByLBPair; // lbPair => vault
    mapping(address => VaultInfo) private _vaultInfo; // vault => VaultInfo
    mapping(address => address[]) private _vaultsByCreator; // creator => vaults[]

    // ============ Constructor ============

    constructor(address initialOwner) Ownable(initialOwner) {
        // Factory owner can set beacon and manage factory
    }

    // ============ View Functions ============

    /**
     * @notice Get the address of the Vault Beacon
     * @return beacon The address of the Beacon
     */
    function getVaultBeacon() external view override returns (address beacon) {
        return _vaultBeacon;
    }

    /**
     * @notice Get the number of vaults created
     * @return The number of vaults
     */
    function getNumberOfVaults() external view override returns (uint256) {
        return _allVaults.length;
    }

    /**
     * @notice Get vault at a specific index
     * @param index The index
     * @return vault The vault address
     */
    function getVaultAtIndex(uint256 index) external view override returns (ILiteTurboVault vault) {
        return _allVaults[index];
    }

    /**
     * @notice Get vault by its LBPair address
     * @param lbPair The LBPair address
     * @return vault The vault address (address(0) if not exists)
     */
    function getVaultByLBPair(address lbPair) external view override returns (ILiteTurboVault vault) {
        return _vaultByLBPair[lbPair];
    }

    /**
     * @notice Get comprehensive info about a vault
     * @param vault The vault address
     * @return info The VaultInfo struct
     */
    function getVaultInfo(address vault) external view override returns (VaultInfo memory info) {
        return _vaultInfo[vault];
    }

    /**
     * @notice Get all vaults
     * @return vaults Array of all vault addresses
     */
    function getAllVaults() external view override returns (address[] memory vaults) {
        uint256 length = _allVaults.length;
        vaults = new address[](length);

        for (uint256 i = 0; i < length; i++) {
            vaults[i] = address(_allVaults[i]);
        }
    }

    /**
     * @notice Get all vaults created by a specific address
     * @param creator The creator address
     * @return vaults Array of vault addresses
     */
    function getVaultsByCreator(address creator) external view override returns (address[] memory vaults) {
        return _vaultsByCreator[creator];
    }

    // ============ Main Functions ============

    /**
     * @notice Create a new LiteTurboVault using Beacon Proxy
     * @dev The caller (msg.sender) becomes the owner of the vault
     * @param lbPair The LBPair address to manage
     * @return vault The deployed vault
     */
    function createVault(
        address lbPair
    ) external override onlyOwner returns (ILiteTurboVault vault) {
        // Validations
        if (lbPair == address(0)) revert VaultFactory__AddressZero();
        if (_vaultBeacon == address(0)) revert VaultFactory__BeaconNotSet();
        if (address(_vaultByLBPair[lbPair]) != address(0)) {
            revert VaultFactory__VaultAlreadyExists(lbPair);
        }

        // Verify lbPair is valid
        try ILBPair(lbPair).getTokenX() returns (IERC20) {
            // Valid pair
        } catch {
            revert VaultFactory__InvalidPair();
        }

        // Encode initialization data - msg.sender becomes vault owner
        bytes memory data = abi.encodeWithSelector(
            ILiteTurboVault.initialize.selector,
            lbPair,
            msg.sender
        );

        // Deploy vault as BeaconProxy
        bytes32 salt = keccak256(abi.encodePacked(lbPair, msg.sender, block.timestamp));
        BeaconProxy proxy = new BeaconProxy{salt: salt}(_vaultBeacon, data);
        vault = ILiteTurboVault(address(proxy));

        // Store vault info
        VaultInfo memory info = VaultInfo({
            vault: vault,
            lbPair: ILBPair(lbPair),
            creator: msg.sender,
            createdAt: block.timestamp
        });

        _allVaults.push(vault);
        _vaultByLBPair[lbPair] = vault;
        _vaultInfo[address(vault)] = info;
        _vaultsByCreator[msg.sender].push(address(vault));

        emit VaultCreated(
            address(vault),
            lbPair,
            msg.sender,
            _allVaults.length - 1
        );
    }

    // ============ Admin Functions ============

    /**
     * @notice Set the Vault Beacon address
     * @dev Only owner can call
     * @param beaconAddress The new beacon address
     */
    function setVaultBeacon(address beaconAddress) external override onlyOwner {
        if (beaconAddress == address(0)) revert VaultFactory__AddressZero();

        address oldBeacon = _vaultBeacon;
        if (oldBeacon == beaconAddress) revert VaultFactory__SameBeacon(beaconAddress);

        _vaultBeacon = beaconAddress;

        emit VaultBeaconSet(oldBeacon, beaconAddress);
    }
}

