// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {ILBPair} from "../../interfaces/ILBPair.sol";
import {ILiteTurboVault} from "./ILiteTurboVault.sol";

interface IVaultFactory {

    // ============ Structs ============

    struct VaultInfo {
        ILiteTurboVault vault;
        ILBPair lbPair;
        address creator;
        uint256 createdAt;
    }

    // ============ Events ============

    event VaultCreated(
        address indexed vault,
        address indexed lbPair,
        address indexed creator,
        uint256 index
    );

    event VaultBeaconSet(
        address indexed oldBeacon,
        address indexed newBeacon
    );

    // ============ Errors ============

    error VaultFactory__AddressZero();
