// SPDX-License-Identifier: MIT

pragma solidity ^0.8.10;

import {PackedUint128Math} from "./PackedUint128Math.sol";
import {Encoded} from "./Encoded.sol";

/**
 * @title Liquidity Book Liquidity Configurations Library
 * @author Trader Joe
 * @notice This library contains functions to encode and decode the config of a pool and interact with the encoded bytes32.
 */
library LiquidityConfigurations {
    using PackedUint128Math for bytes32;
    using PackedUint128Math for uint128;
    using Encoded for bytes32;

    error LiquidityConfigurations__InvalidConfig();

    uint256 private constant OFFSET_ID = 0;
    uint256 private constant OFFSET_DISTRIBUTION_Y = 24;
    uint256 private constant OFFSET_DISTRIBUTION_X = 88;

    uint256 private constant PRECISION = 1e18;

    /**
     * @dev Encode the distributionX, distributionY and id into a single bytes32
     * @param distributionX The distribution of the first token
     * @param distributionY The distribution of the second token
     * @param id The id of the pool
     * @return config The encoded config as follows:
     * [0 - 24[: id
     * [24 - 88[: distributionY
     * [88 - 152[: distributionX
     * [152 - 256[: empty
     */
    function encodeParams(uint64 distributionX, uint64 distributionY, uint24 id)
        internal
        pure
        returns (bytes32 config)
    {
        config = config.set(distributionX, Encoded.MASK_UINT64, OFFSET_DISTRIBUTION_X);
        config = config.set(distributionY, Encoded.MASK_UINT64, OFFSET_DISTRIBUTION_Y);
        config = config.set(id, Encoded.MASK_UINT24, OFFSET_ID);
    }

    /**
     * @dev Decode the distributionX, distributionY and id from a single bytes32
     * @param config The encoded config as follows:
     * [0 - 24[: id
     * [24 - 88[: distributionY
     * [88 - 152[: distributionX
     * [152 - 256[: empty
     * @return distributionX The distribution of the first token
     * @return distributionY The distribution of the second token
     * @return id The id of the bin to add the liquidity to
     */
    function decodeParams(bytes32 config)
        internal
        pure
        returns (uint64 distributionX, uint64 distributionY, uint24 id)
    {
        distributionX = config.decodeUint64(OFFSET_DISTRIBUTION_X);
        distributionY = config.decodeUint64(OFFSET_DISTRIBUTION_Y);
        id = config.decodeUint24(OFFSET_ID);

        if (uint256(config) > type(uint152).max || distributionX > PRECISION || distributionY > PRECISION) {
            revert LiquidityConfigurations__InvalidConfig();
        }
    }

    /**
     * @dev Get the amounts and id from a config and amountsIn
     * @param config The encoded config as follows:
     * [0 - 24[: id
     * [24 - 88[: distributionY
     * [88 - 152[: distributionX
     * [152 - 256[: empty
     * @param amountsIn The amounts to distribute as follows:
     * [0 - 128[: x1
     * [128 - 256[: x2
     * @return amounts The distributed amounts as follows:
     * [0 - 128[: x1
     * [128 - 256[: x2
     * @return id The id of the bin to add the liquidity to
     */
    function getAmountsAndId(bytes32 config, bytes32 amountsIn) internal pure returns (bytes32, uint24) {
        (uint64 distributionX, uint64 distributionY, uint24 id) = decodeParams(config);

        (uint128 x1, uint128 x2) = amountsIn.decode();

        assembly {
            x1 := div(mul(x1, distributionX), PRECISION)
            x2 := div(mul(x2, distributionY), PRECISION)
        }

        return (x1.encode(x2), id);
    }
}

src/LBTokenUpgrade.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.20;

import {ILBToken} from "./interfaces/ILBToken.sol";
import {ILBToken} from "./interfaces/ILBToken.sol";
import {Uint256x256Math} from "./libraries/math/Uint256x256Math.sol";
import {SafeCast} from "./libraries/math/SafeCast.sol";
import {Constants} from "./libraries/Constants.sol";
import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

/**
 * @title Liquidity Book Token Upgradeable
 * @author Bean Exchange
 * @notice The LBTokenUpgradeable is an upgradeable implementation of a multi-token using ERC-7201 storage pattern.
 * It allows to create multi-ERC20 represented by their ids.
 * Its implementation is really similar to the ERC1155 standard the main difference
 * is that it doesn't do any call to the receiver contract to prevent reentrancy.
 * As it's only for ERC20s, the uri function is not implemented.
 * The contract is made for batch operations and includes fee/reward tracking.
 */
abstract contract LBTokenUpgradeable is Initializable, ILBToken {
    using Uint256x256Math for uint256;
    using SafeCast for uint256;

    /// @custom:storage-location erc7201:beanexchange.storage.LBToken
    struct LBTokenStorage {
        // Core token balances
        mapping(address account => mapping(uint256 id => uint256 balance)) _balances;
        mapping(uint256 id => uint256 supply) _totalSupplies;
        mapping(address owner => mapping(address spender => bool approved)) _spenderApprovals;

        // Fee and reward tracking
        mapping(uint256 id => ILBToken.BinFeeData feeData) _binFees;
        mapping(address account => mapping(uint256 id => ILBToken.PositionFeeInfo feeInfo)) _positionFees;
    }

    // keccak256(abi.encode(uint256(keccak256("beanexchange.storage.LBToken")) - 1)) & ~bytes32(uint256(0xff))
    // solhint-disable-next-line const-name-snakecase
    bytes32 private constant LBTokenStorageLocation = 0x2e6b031a38e589472ff6f6d0c8cea56a2e4b0756fab46edf3097bfd1face4b00;

    function _getLBTokenStorage() private pure returns (LBTokenStorage storage $) {
        // solhint-disable-next-line no-inline-assembly
        assembly {
            $.slot := LBTokenStorageLocation
        }
    }

    /**
     * @dev Modifier to check if the spender is approved for all.
     */
    modifier checkApproval(address from, address spender) {
        if (!_isApprovedForAll(from, spender)) revert LBToken__SpenderNotApproved(from, spender);
        _;
    }

    /**
     * @dev Modifier to check if the address is not zero or the contract itself.
     */
    modifier notAddressZeroOrThis(address account) {
        _notAddressZeroOrThis(account);
        _;
    }

    /**
     * @dev Modifier to check if the length of the arrays are equal.
     */
    modifier checkLength(uint256 lengthA, uint256 lengthB) {
        _checkLength(lengthA, lengthB);
        _;
    }

    /**
     * @notice Returns the name of the token.
     * @return The name of the token.
     */
    function name() public view virtual override returns (string memory) {
        return "Liquidity Book Token";
    }

    /**
     * @notice Returns the symbol of the token, usually a shorter version of the name.
     * @return The symbol of the token.
     */
    function symbol() public view virtual override returns (string memory) {
        return "LBT";
    }

    /**
     * @notice Returns the total supply of token of type `id`.
     * @dev This is the amount of token of type `id` minted minus the amount burned.
     * @param id The token id.
     * @return The total supply of that token id.
     */
    function totalSupply(uint256 id) public view virtual override returns (uint256) {
        LBTokenStorage storage $ = _getLBTokenStorage();
        return $._totalSupplies[id];
    }

    /**
     * @notice Returns the amount of tokens of type `id` owned by `account`.
     * @param account The address of the owner.
     * @param id The token id.
     * @return The amount of tokens of type `id` owned by `account`.
     */
    function balanceOf(address account, uint256 id) public view virtual override returns (uint256) {
        LBTokenStorage storage $ = _getLBTokenStorage();
        return $._balances[account][id];
    }

    /**
     * @notice Return the balance of multiple (account/id) pairs.
     * @param accounts The addresses of the owners.
     * @param ids The token ids.
     * @return batchBalances The balance for each (account, id) pair.
     */
    function balanceOfBatch(address[] calldata accounts, uint256[] calldata ids)
        public
        view
        virtual
        override
        checkLength(accounts.length, ids.length)
        returns (uint256[] memory batchBalances)
    {
        batchBalances = new uint256[](accounts.length);

        unchecked {
            for (uint256 i; i < accounts.length; ++i) {
                batchBalances[i] = balanceOf(accounts[i], ids[i]);
            }
        }
    }

    /**
     * @notice Returns true if `spender` is approved to transfer `owner`'s tokens or if `spender` is the `owner`.
     * @param owner The address of the owner.
     * @param spender The address of the spender.
     * @return True if `spender` is approved to transfer `owner`'s tokens.
     */
    function isApprovedForAll(address owner, address spender) public view virtual override returns (bool) {
        return _isApprovedForAll(owner, spender);
    }

    /**
     * @notice Grants or revokes permission to `spender` to transfer the caller's lbTokens, according to `approved`.
     * @param spender The address of the spender.
     * @param approved The boolean value to grant or revoke permission.
     */
    function approveForAll(address spender, bool approved) public virtual override {
        _approveForAll(msg.sender, spender, approved);
    }

    /**
     * @notice Batch transfers `amounts` of `ids` from `from` to `to`.
     * @param from The address of the owner.
     * @param to The address of the recipient.
     * @param ids The list of token ids.
     * @param amounts The list of amounts to transfer for each token id in `ids`.
     */
    function batchTransferFrom(address from, address to, uint256[] calldata ids, uint256[] calldata amounts)
        public
        virtual
        override
        checkApproval(from, msg.sender)
    {
        _batchTransferFrom(from, to, ids, amounts);
    }

    /**
     * @notice Get bin fee data.
     * @param id The bin id.
     * @return The bin fee data.
     */
    function getBinFeeData(uint256 id) external view override returns (BinFeeData memory) {
        LBTokenStorage storage $ = _getLBTokenStorage();
        return $._binFees[id];
    }

    /**
     * @notice Get position fee info.
     * @param account The account address.
     * @param id The bin id.
     * @return The position fee info.
     */
    function getPositionFeeInfo(address account, uint256 id) external view override returns (PositionFeeInfo memory) {
        LBTokenStorage storage $ = _getLBTokenStorage();
        return $._positionFees[account][id];
    }

    /**
     * @notice Get pending fees for a position.
     * @param account The account address.
     * @param id The bin id.
     * @return pendingX Pending fees in token X.
     * @return pendingY Pending fees in token Y.
     */
    function getPendingFee(address account, uint256 id) public view override returns (uint128 pendingX, uint128 pendingY) {
        LBTokenStorage storage $ = _getLBTokenStorage();
        uint256 balance = $._balances[account][id];

        BinFeeData memory binFee = $._binFees[id];
        PositionFeeInfo memory position = $._positionFees[account][id];

        uint128 tokensOwedX = (position.tokensOwedX.mulShiftRoundDown(Constants.ONE, Constants.SCALE_OFFSET)).safe128();
        uint128 tokensOwedY = (position.tokensOwedY.mulShiftRoundDown(Constants.ONE, Constants.SCALE_OFFSET)).safe128();

        if (balance == 0) return (tokensOwedX, tokensOwedY);

        uint256 scaledEarnedX = _calculateFeesEarned(
            balance,
            binFee.feeGrowthX128,
            position.feeGrowthX128Last
        );

        uint256 scaledEarnedY = _calculateFeesEarned(
            balance,
            binFee.feeGrowthY128,
            position.feeGrowthY128Last
        );

        uint128 earnedX = scaledEarnedX.mulShiftRoundDown(Constants.ONE, Constants.SCALE_OFFSET).safe128();
        uint128 earnedY = scaledEarnedY.mulShiftRoundDown(Constants.ONE, Constants.SCALE_OFFSET).safe128();

        uint128 totalX = uint128(tokensOwedX) + earnedX;
        uint128 totalY = uint128(tokensOwedY) + earnedY;

        pendingX = totalX;
        pendingY = totalY;
    }

    /**
     * @notice Check if a position is locked.
     * @param account The account address.
     * @param id The bin id.
     * @return locked Whether the position is locked.
     * @return until The timestamp until which the position is locked.
     */
    function isPositionLocked(address account, uint256 id) external view override returns (bool locked, uint256 until) {
        LBTokenStorage storage $ = _getLBTokenStorage();
        until = $._positionFees[account][id].lockUntil;
        locked = until > block.timestamp;
    }

    /**
     * @notice Returns true if `spender` is approved to transfer `owner`'s tokens or if `spender` is the `owner`.
     * @param owner The address of the owner.
     * @param spender The address of the spender.
     * @return True if `spender` is approved to transfer `owner`'s tokens.
     */
    function _isApprovedForAll(address owner, address spender) internal view returns (bool) {
        LBTokenStorage storage $ = _getLBTokenStorage();
        return owner == spender || $._spenderApprovals[owner][spender];
    }

    /**
     * @dev Update bin fee growth when swap generates fees.
     * @param binId The bin id.
     * @param feesX Fees in token X.
     * @param feesY Fees in token Y.
     */
    function _updateBinFeeGrowth(uint256 binId, uint128 feesX, uint128 feesY) internal {
        LBTokenStorage storage $ = _getLBTokenStorage();
        uint256 _totalSupply = $._totalSupplies[binId];
        if (_totalSupply == 0) return;

        BinFeeData storage binFee = $._binFees[binId];

        if (feesX > 0) {
            uint256 deltaGrowthX = uint256(feesX).mulDivRoundDown(
                Constants.SCALE,
                _totalSupply
            );
            binFee.feeGrowthX128 = binFee.feeGrowthX128 + deltaGrowthX;
        }

        if (feesY > 0) {
            uint256 deltaGrowthY = uint256(feesY).mulDivRoundDown(
                Constants.SCALE,
                _totalSupply
            );
            binFee.feeGrowthY128 = binFee.feeGrowthY128 + deltaGrowthY;
        }

        emit FeeGrowthUpdated(binId, binFee.feeGrowthX128, binFee.feeGrowthY128);
    }

    /**
     * @dev Update bin rewards when emission occurs.
     * @param binId The bin ID.
     * @param rewardEmissions Array of reward emissions per rewarder.
     */
    function _updateBinRewardGrowth(uint256 binId, uint256[] memory rewardEmissions) internal {
        LBTokenStorage storage $ = _getLBTokenStorage();
        uint256 _totalSupply = $._totalSupplies[binId];

        BinFeeData storage binFee = $._binFees[binId];

        uint256 currentLength = binFee.rewardGrowth128.length;
        if (currentLength < rewardEmissions.length) {
            for (uint256 i = currentLength; i < rewardEmissions.length; i++) {
                binFee.rewardGrowth128.push(0);
            }
        }
        if (_totalSupply == 0) return;

        for (uint256 i = 0; i < rewardEmissions.length; i++) {
            if (rewardEmissions[i] > 0) {
                uint256 deltaGrowth = rewardEmissions[i].mulDivRoundDown(
                    Constants.SCALE,
                    _totalSupply
                );
                binFee.rewardGrowth128[i] = binFee.rewardGrowth128[i] + deltaGrowth;
            }
        }

        emit RewardGrowthUpdated(binId, binFee.rewardGrowth128);
    }

    /**
     * @dev Simulate update reward growth.
     * @param binId The bin id.
     * @param rewardEmissions Reward emissions.
     * @return Updated reward growth array.
     */
    function _simulateUpdateRewardGrowth(uint256 binId, uint256[] memory rewardEmissions) 
        internal 
        view 
        returns (uint256[] memory) 
    {
        LBTokenStorage storage $ = _getLBTokenStorage();
        uint256 _totalSupply = $._totalSupplies[binId];

        BinFeeData memory binFee = $._binFees[binId];

        uint256 binLength = binFee.rewardGrowth128.length;
        uint256 currentLength = binLength < rewardEmissions.length ? rewardEmissions.length : binLength;
        if (_totalSupply == 0) return new uint256[](currentLength);

        uint256[] memory rewardGrowth128 = new uint256[](currentLength);
        for (uint256 i = 0; i < currentLength; i++) {
            if (i < binLength) {
                rewardGrowth128[i] = binFee.rewardGrowth128[i];
        } else {
                rewardGrowth128[i] = 0;
            }
        }

        for (uint256 i = 0; i < rewardEmissions.length; i++) {
            if (rewardEmissions[i] > 0) {
                uint256 deltaGrowth = rewardEmissions[i].mulDivRoundDown(
                    Constants.SCALE,
                    _totalSupply
                );
                if (i < binLength) {
                    rewardGrowth128[i] = binFee.rewardGrowth128[i] + deltaGrowth;
                } else {
                    rewardGrowth128[i] = deltaGrowth; 
                }
            }
        }

        return rewardGrowth128;
    }

    /**
     * @dev Settle rewards for a position before balance changes.
     * @param account The account address.
     * @param binId The bin id.
     */
    function _settlePositionRewards(address account, uint256 binId) internal {
        LBTokenStorage storage $ = _getLBTokenStorage();
        uint256 balance = $._balances[account][binId];

        BinFeeData memory binFee = $._binFees[binId];
        PositionFeeInfo storage position = $._positionFees[account][binId];

        uint256 rewardLength = binFee.rewardGrowth128.length;
        if (rewardLength == 0) return;

        uint256 positionLength = position.rewardGrowth128Last.length;
        if (positionLength < rewardLength) {
            for (uint256 i = positionLength; i < rewardLength; i++) {
                position.rewardGrowth128Last.push(0);
                position.tokensOwedRewards.push(0);
            }
        }

        for (uint256 i = 0; i < rewardLength; i++) {
            uint256 currentGrowth = binFee.rewardGrowth128[i];
            uint256 lastGrowth = 0;
            if (position.rewardGrowth128Last.length > 0) {
                lastGrowth = position.rewardGrowth128Last[i];
            }

            if (balance == 0) {
                position.rewardGrowth128Last[i] = currentGrowth;
                continue;
            }

            if (currentGrowth > lastGrowth) {
                uint256 growthDelta = currentGrowth - lastGrowth;
                uint256 rewardEarned = balance.mulShiftRoundDown(growthDelta, 128);
                uint256 newOwed = uint256(position.tokensOwedRewards[i]) + rewardEarned;
                position.tokensOwedRewards[i] = newOwed;
            }

            position.rewardGrowth128Last[i] = currentGrowth;
        }
    }

    /**
     * @dev Collect rewards for a specific rewarder index.
     * @param account The position owner.
     * @param binId The bin ID.
     * @param rewarderIndex Index of the rewarder.
     * @return collected Amount of rewards collected.
     */
    function _collectPositionRewardPerIndex(
        address account,
        uint256 binId,
        uint256 rewarderIndex
    ) private returns (uint128 collected) {
        _settlePositionRewards(account, binId);

        LBTokenStorage storage $ = _getLBTokenStorage();
        PositionFeeInfo storage position = $._positionFees[account][binId];

        if (rewarderIndex < position.tokensOwedRewards.length) {
            uint256 scaledAmount = position.tokensOwedRewards[rewarderIndex];
            collected = (scaledAmount >> 128).safe128();

            if (collected > 0) {
                position.tokensOwedRewards[rewarderIndex] = 0;
            }
        }
    }

    /**
     * @dev Collect rewards.
     * @param account The position owner.
     * @param binId The bin ID.
     * @return collecteds Amount of rewards collected.
     */
    function _collectPositionReward(
        address account,
        uint256 binId
    ) internal returns (uint128[] memory collecteds) {
        LBTokenStorage storage $ = _getLBTokenStorage();
        BinFeeData memory binFee = $._binFees[binId];
        collecteds = new uint128[](binFee.rewardGrowth128.length);
        for (uint256 i = 0; i < binFee.rewardGrowth128.length; i++) {
            collecteds[i] = _collectPositionRewardPerIndex(account, binId, i);
        }
    }

    /**
     * @dev Get tokens rewards length.
     * @param binId The bin id.
     * @return The length of rewards array.
     */
    function getTokensRewardsLength(uint256 binId) internal view returns (uint256) {
        LBTokenStorage storage $ = _getLBTokenStorage();
        BinFeeData memory binFee = $._binFees[binId];
        return binFee.rewardGrowth128.length;
    }

    /**
     * @dev Calculate fees earned.
     * @param liquidity The liquidity amount.
     * @param currentGrowth Current fee growth.
     * @param lastGrowth Last recorded fee growth.
     * @return earned Fees earned.
     */
    function _calculateFeesEarned(
        uint256 liquidity,
        uint256 currentGrowth,
        uint256 lastGrowth
    ) internal pure returns (uint256 earned) {
        if (currentGrowth >= lastGrowth) {
            uint256 growthDelta = currentGrowth - lastGrowth;
            earned = liquidity.mulDivRoundDown(growthDelta, Constants.ONE);
        }
    }

    /**
     * @dev Settle fees before balance changes.
     * @param account The account address.
     * @param binId The bin id.
     */
    function _settleFees(address account, uint256 binId) internal {
        LBTokenStorage storage $ = _getLBTokenStorage();
        uint256 balance = $._balances[account][binId];
        BinFeeData memory binFee = $._binFees[binId];
        PositionFeeInfo storage position = $._positionFees[account][binId];

        if (balance > 0) {
            uint256 earnedX = _calculateFeesEarned(
                balance,
                binFee.feeGrowthX128,
                position.feeGrowthX128Last
            );

            uint256 earnedY = _calculateFeesEarned(
                balance,
                binFee.feeGrowthY128,
                position.feeGrowthY128Last
            );

            if (earnedX > 0 || earnedY > 0) {
                uint256 newOwedX = uint256(position.tokensOwedX) + earnedX;
                uint256 newOwedY = uint256(position.tokensOwedY) + earnedY;

                position.tokensOwedX = newOwedX;
                position.tokensOwedY = newOwedY;

                emit FeesSettled(account, binId, earnedX, earnedY);
            }
        }

        _settlePositionRewards(account, binId);

        position.feeGrowthX128Last = binFee.feeGrowthX128;
        position.feeGrowthY128Last = binFee.feeGrowthY128;
    }

    /**
     * @dev Collect position fees.
     * @param account The account address.
     * @param binId The bin id.
     * @return collectedX Collected fees in token X.
     * @return collectedY Collected fees in token Y.
     */
    function _collectPositionFees(
        address account,
        uint256 binId
    ) internal returns (uint128 collectedX, uint128 collectedY) {
        _settleFees(account, binId);

        LBTokenStorage storage $ = _getLBTokenStorage();
        PositionFeeInfo storage position = $._positionFees[account][binId];
        collectedX = (position.tokensOwedX.mulShiftRoundDown(Constants.ONE, Constants.SCALE_OFFSET)).safe128();
        collectedY = (position.tokensOwedY.mulShiftRoundDown(Constants.ONE, Constants.SCALE_OFFSET)).safe128();

        if (collectedX > 0 || collectedY > 0) {
            position.tokensOwedX = 0;
            position.tokensOwedY = 0;
        }
    }

    /**
     * @dev Get pending rewards for all rewarders.
     * @param account The position owner.
     * @param binId The bin ID.
     * @param binRewardGrowths Bin reward growths.
     * @return pending Array of pending rewards per rewarder.
     */
    function getPendingReward(
        address account,
        uint256 binId,
        uint256[] memory binRewardGrowths
    ) public view returns (uint128[] memory pending) {
        LBTokenStorage storage $ = _getLBTokenStorage();
        uint256 balance = $._balances[account][binId];

        BinFeeData memory binFee = $._binFees[binId];
        PositionFeeInfo memory position = $._positionFees[account][binId];

        uint128[] memory tokensOwedRewards = new uint128[](position.tokensOwedRewards.length);
        for (uint256 i = 0; i < tokensOwedRewards.length; i++) {
            tokensOwedRewards[i] = (position.tokensOwedRewards[i].mulDivRoundDown(Constants.ONE, Constants.SCALE)).safe128();
        }

        if (balance == 0) return tokensOwedRewards;

        uint256 rewardLength = binRewardGrowths.length;
        pending = new uint128[](rewardLength);

        if (rewardLength == 0) {
            binRewardGrowths = new uint256[](binFee.rewardGrowth128.length);
            for (uint256 i = 0; i < binFee.rewardGrowth128.length; i++) {
                binRewardGrowths[i] = binFee.rewardGrowth128[i];
            }
        }

        for (uint256 i = 0; i < rewardLength; i++) {
            uint256 currentGrowth = binRewardGrowths[i];
            uint256 lastGrowth = i < position.rewardGrowth128Last.length ? 
                                position.rewardGrowth128Last[i] : 0;

            if (currentGrowth > lastGrowth) {
                uint256 scaledGrowthDelta = currentGrowth - lastGrowth;
                uint256 growthDelta = scaledGrowthDelta.mulShiftRoundDown(Constants.ONE, Constants.SCALE_OFFSET);
                uint256 earned = balance.mulShiftRoundDown(growthDelta, Constants.SCALE_OFFSET);
                pending[i] = earned.safe128();
            }

            if (i < position.tokensOwedRewards.length) {
                uint256 total = uint256(pending[i]) + tokensOwedRewards[i];
                pending[i] = total.safe128();
            }
        }
    }

    /**
     * @dev Set position lock.
     * @param account The account address.
     * @param binId The bin id.
     * @param lockUntil Lock timestamp.
     */
    function _setPositionLock(address account, uint256 binId, uint256 lockUntil) internal {
        LBTokenStorage storage $ = _getLBTokenStorage();
        PositionFeeInfo storage position = $._positionFees[account][binId];
        uint256 currentLock = position.lockUntil;

        if (currentLock > block.timestamp && lockUntil < currentLock) {
            revert LBToken__CannotReduceLockTime(currentLock, lockUntil);
        }

        if (lockUntil != 0 && lockUntil <= block.timestamp) {
            revert LBToken__InvalidLockTime();
        }

        position.lockUntil = lockUntil;

        if (lockUntil > 0) {
            emit PositionLocked(account, binId, lockUntil);
        }
    }

    /**
     * @dev Mint `amount` of `id` to `account`.
     * @param account The address of the owner.
     * @param id The token id.
     * @param amount The amount to mint.
     */
    function _mint(address account, uint256 id, uint256 amount) internal virtual {
        LBTokenStorage storage $ = _getLBTokenStorage();
        _settleFees(account, id);
        $._totalSupplies[id] += amount;

        unchecked {
            $._balances[account][id] += amount;
        }
    }

    /**
     * @dev Burn `amount` of `id` from `account`.
     * @param account The address of the owner.
     * @param id The token id.
     * @param amount The amount to burn.
     */
    function _burn(address account, uint256 id, uint256 amount) internal virtual {
        LBTokenStorage storage $ = _getLBTokenStorage();

        PositionFeeInfo storage position = $._positionFees[account][id];
        if (position.lockUntil > block.timestamp) {
            revert LBToken__PositionLocked(account, id, position.lockUntil);
        }

        _settleFees(account, id);

        mapping(uint256 => uint256) storage accountBalances = $._balances[account];

        uint256 balance = accountBalances[id];
        if (balance < amount) revert LBToken__BurnExceedsBalance(account, id, amount);

        unchecked {
            $._totalSupplies[id] -= amount;
            accountBalances[id] = balance - amount;
        }
    }

    /**
     * @dev Batch transfers `amounts` of `ids` from `from` to `to`.
     * @param from The address of the owner.
     * @param to The address of the recipient.
     * @param ids The list of token ids.
     * @param amounts The list of amounts to transfer for each token id in `ids`.
     */
    function _batchTransferFrom(address from, address to, uint256[] calldata ids, uint256[] calldata amounts)
        internal
        checkLength(ids.length, amounts.length)
        notAddressZeroOrThis(to)
    {
        for (uint256 i; i < ids.length;) {
            _processSingleTransfer(from, to, ids[i], amounts[i]);
            unchecked {
                ++i;
            }
        }

        emit TransferBatch(msg.sender, from, to, ids, amounts);
    }

    /**
     * @dev Process a single transfer with lock check and fee settlement.
     * @param from The address of the owner.
     * @param to The address of the recipient.
     * @param id The token id.
     * @param amount The amount to transfer.
     */
    function _processSingleTransfer(address from, address to, uint256 id, uint256 amount) private {
        LBTokenStorage storage $ = _getLBTokenStorage();

        {
            PositionFeeInfo storage position = $._positionFees[from][id];
            if (position.lockUntil > block.timestamp) {
                revert LBToken__PositionLocked(from, id, position.lockUntil);
            }
        }

        _settleFees(from, id);
        _settleFees(to, id);

        {
            mapping(uint256 => uint256) storage fromBalances = $._balances[from];
            mapping(uint256 => uint256) storage toBalances = $._balances[to];

            uint256 fromBalance = fromBalances[id];
            if (fromBalance < amount) revert LBToken__TransferExceedsBalance(from, id, amount);

            unchecked {
                fromBalances[id] = fromBalance - amount;
                toBalances[id] += amount;
            }
        }
    }

    /**
     * @notice Grants or revokes permission to `spender` to transfer the caller's tokens, according to `approved`.
     * @param owner The address of the owner.
     * @param spender The address of the spender.
     * @param approved The boolean value to grant or revoke permission.
     */
    function _approveForAll(address owner, address spender, bool approved) internal notAddressZeroOrThis(owner) {
        if (owner == spender) revert LBToken__SelfApproval(owner);

        LBTokenStorage storage $ = _getLBTokenStorage();
        $._spenderApprovals[owner][spender] = approved;
        emit ApprovalForAll(owner, spender, approved);
    }

    /**
     * @dev Reverts if the address is the zero address or the contract itself.
     * @param account The address to check.
     */
    function _notAddressZeroOrThis(address account) internal view {
        if (account == address(0) || account == address(this)) revert LBToken__AddressThisOrZero();
    }

    /**
     * @dev Reverts if the length of the arrays are not equal.
     * @param lengthA The length of the first array.
     * @param lengthB The length of the second array.
     */
    function _checkLength(uint256 lengthA, uint256 lengthB) internal pure {
        if (lengthA != lengthB) revert LBToken__InvalidLength();
    }
}

