// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {ILBRewarder} from "./interfaces/ILBRewarder.sol";
import {ILBRewarderVault} from "./interfaces/ILBRewarderVault.sol";
import {SafeMath} from "./libraries/math/SafeMath.sol";
import {SafeCast} from "./libraries/math/SafeCast.sol";
import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

/**
 * @title LBRewarderUpgradeable
 * @author Bean Exchange
 * @notice Upgradeable rewarder logic contract to be inherited by LBPair using ERC-7201 storage pattern.
 * @dev Handles emission calculations and reward distribution logic.
 */
abstract contract LBRewarderUpgradeable is Initializable, ILBRewarder {
    using SafeMath for uint256;
    using SafeCast for uint256;

    // Additional custom errors
    error LBRewarder__InsufficientVaultBalance();
    error LBRewarder__InvalidIndex();

    // Constants
    uint256 public constant MAX_REWARDERS_PER_PAIR = 5;
    uint256 public constant PRECISION_SHIFT = 128;

    // Structs for internal use
    struct RewarderManager {
        Rewarder[] rewarders;
        uint128 lastUpdateTimestamp;
        mapping(address => uint256) rewarderIndex; 
    }

    /// @custom:storage-location erc7201:beanexchange.storage.LBRewarder
    struct LBRewarderStorage {
        RewarderManager _rewarderManager;
        ILBRewarderVault rewarderVault;
    }

    // keccak256(abi.encode(uint256(keccak256("beanexchange.storage.LBRewarder")) - 1)) & ~bytes32(uint256(0xff))
    // solhint-disable-next-line const-name-snakecase
    bytes32 private constant LBRewarderStorageLocation = 0x83a78bec631009b1f2fc9fd5f475b2a5021ae70918eed1a461deabac54b20900;

    function _getLBRewarderStorage() internal pure returns (LBRewarderStorage storage $) {
        // solhint-disable-next-line no-inline-assembly
        assembly {
            $.slot := LBRewarderStorageLocation
        }
    }

    // /**
    //  * @dev Initializes the LBRewarder contract.
    //  * @param _vault The address of the rewarder vault.
    //  */
    // // solhint-disable-next-line func-name-mixedcase
    // function __LBRewarder_init(address _vault) internal onlyInitializing {
    //     __LBRewarder_init_unchained(_vault);
    // }

    // // solhint-disable-next-line func-name-mixedcase
    // function __LBRewarder_init_unchained(address _vault) internal onlyInitializing {
    //     _initRewarderStorage(_vault);
    // }

    /**
     * @dev Internal function to initialize rewarder storage (can be called outside initializer)
     * @param _vault The address of the rewarder vault.
     */
    function _initRewarderStorage(address _vault) internal {
        LBRewarderStorage storage $ = _getLBRewarderStorage();
        $.rewarderVault = ILBRewarderVault(_vault);
        $._rewarderManager.lastUpdateTimestamp = 0;
    }

    /**
     * @notice Get the rewarder vault address.
     * @return The address of the rewarder vault.
     */
    function rewarderVault() public view override returns (address) {
        LBRewarderStorage storage $ = _getLBRewarderStorage();
        return address($.rewarderVault);
    }

    /**
     * @dev Add a new rewarder (internal for LBPair to expose with access control).
     * @param rewardToken The address of the reward token.
     */
    function _addRewarder(address rewardToken) internal {
        LBRewarderStorage storage $ = _getLBRewarderStorage();

        if ($._rewarderManager.rewarders.length >= MAX_REWARDERS_PER_PAIR) {
            revert TooManyRewarders();
        }

        if ($._rewarderManager.rewarderIndex[rewardToken] != 0) {
            revert RewarderAlreadyExists();
        }

        $._rewarderManager.rewarders.push(Rewarder({
            emissionPerSecond: 0,
            rewardToken: rewardToken,
            exists: true
        }));

        $._rewarderManager.rewarderIndex[rewardToken] = $._rewarderManager.rewarders.length;

        emit RewarderAdded(rewardToken);
    }

    /**
     * @dev Update emission rate (internal for LBPair to expose with access control).
     * @param rewardToken The address of the reward token.
     * @param newRate The new emission rate in Q128.128 format.
     */
    function _updateEmissionRate(address rewardToken, uint256 newRate) internal {
        LBRewarderStorage storage $ = _getLBRewarderStorage();
        uint256 index = $._rewarderManager.rewarderIndex[rewardToken];
        if (index == 0) revert RewarderNotFound();

        if (newRate > 0) {
            uint256 vaultBalance = $.rewarderVault.balanceOf(rewardToken);
            uint256 oneDayEmissions = (86400 * newRate) >> 128; // 1 day in seconds

            if (vaultBalance < oneDayEmissions) revert LBRewarder__InsufficientVaultBalance();
        }

        Rewarder storage rewarder = $._rewarderManager.rewarders[index - 1];
        uint256 oldRate = rewarder.emissionPerSecond;
        rewarder.emissionPerSecond = newRate;

        emit EmissionRateUpdated(rewardToken, oldRate, newRate);
    }

    /**
     * @dev Calculate reward emissions for all rewarders.
     * @return emissions Array of emissions for each rewarder.
     */
    function _calculateRewardEmissions() internal returns (uint256[] memory emissions) {
        LBRewarderStorage storage $ = _getLBRewarderStorage();
        uint256 length = $._rewarderManager.rewarders.length;
        emissions = new uint256[](length);

        uint256 currentTime = block.timestamp;
        uint256 lastUpdate = uint256($._rewarderManager.lastUpdateTimestamp);

        if (currentTime > lastUpdate && lastUpdate > 0) {
            uint256 elapsed = currentTime - lastUpdate;

            for (uint256 i = 0; i < length; i++) {
                Rewarder memory rewarder = $._rewarderManager.rewarders[i];
                if (rewarder.emissionPerSecond > 0) {
                    emissions[i] = rewarder.emissionPerSecond.mul(elapsed);
                }
            }
        }

        _setTimeLastUpdateReward();
    }

    /**
     * @dev Simulate calculating reward emissions without updating state.
     * @return emissions Array of emissions for each rewarder.
     */
    function _simulateCalculateRewardEmissions() internal view returns (uint256[] memory emissions) {
        LBRewarderStorage storage $ = _getLBRewarderStorage();
        uint256 length = $._rewarderManager.rewarders.length;
        emissions = new uint256[](length);

        uint256 currentTime = block.timestamp;
        uint256 lastUpdate = uint256($._rewarderManager.lastUpdateTimestamp);

        if (currentTime > lastUpdate && lastUpdate > 0) {
            uint256 elapsed = currentTime - lastUpdate;

            for (uint256 i = 0; i < length; i++) {
                Rewarder memory rewarder = $._rewarderManager.rewarders[i];
                if (rewarder.emissionPerSecond > 0) {
                    emissions[i] = rewarder.emissionPerSecond.mul(elapsed);
                }
            }
        }
    }

    /**
     * @dev Set the last update timestamp to current time.
     */
    function _setTimeLastUpdateReward() internal {
        LBRewarderStorage storage $ = _getLBRewarderStorage();
        uint256 currentTime = block.timestamp;
        $._rewarderManager.lastUpdateTimestamp = currentTime.safe128();
    }

    /**
     * @notice Simulate emissions without updating state.
     * @return emissions Array of simulated emissions.
     */
    function simulateRewardEmissions() public view override returns (uint256[] memory emissions) {
        LBRewarderStorage storage $ = _getLBRewarderStorage();
        uint256 length = $._rewarderManager.rewarders.length;
        emissions = new uint256[](length);

        uint256 currentTime = block.timestamp;
        uint256 lastUpdate = uint256($._rewarderManager.lastUpdateTimestamp);

        if (currentTime > lastUpdate && lastUpdate > 0) {
            uint256 elapsed = currentTime - lastUpdate;

            for (uint256 i = 0; i < length; i++) {
                Rewarder memory rewarder = $._rewarderManager.rewarders[i];
                if (rewarder.emissionPerSecond > 0) {
                    emissions[i] = rewarder.emissionPerSecond.mul(elapsed);
                }
            }
        }
    }

    /**
     * @notice Get rewarder info by index.
     * @param index The index of the rewarder.
     * @return rewardToken The address of the reward token.
     * @return emissionPerSecond The emission rate per second.
     */
    function getRewarder(uint256 index) public view override returns (
        address rewardToken,
        uint256 emissionPerSecond
    ) {
        LBRewarderStorage storage $ = _getLBRewarderStorage();
        if (index >= $._rewarderManager.rewarders.length) revert LBRewarder__InvalidIndex();
        Rewarder memory rewarder = $._rewarderManager.rewarders[index];
        return (rewarder.rewardToken, rewarder.emissionPerSecond);
    }

    /**
     * @notice Get all rewarders.
     * @return Array of all rewarders.
     */
    function getAllRewarders() public view override returns (Rewarder[] memory) {
        LBRewarderStorage storage $ = _getLBRewarderStorage();
        uint256 length = $._rewarderManager.rewarders.length;
        Rewarder[] memory arr = new Rewarder[](length);
        for (uint256 i = 0; i < length; i++) {
            arr[i] = $._rewarderManager.rewarders[i];
        }
        return arr;
    }

    /**
     * @notice Get the number of rewarders.
     * @return The count of rewarders.
     */
    function getRewarderCount() public view override returns (uint256) {
        LBRewarderStorage storage $ = _getLBRewarderStorage();
        return $._rewarderManager.rewarders.length;
    }
}

